begin;

-- Idempotent core case/answer-key seed. Never set DA_DUYET.
insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-chan-thuong-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Cụ bà trượt ngã, đau háng phải, chân ngắn xoay ngoài","setting":"giuong","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":79,"sex":"nữ","patient_label":"Bà N. T. L."},"presentation":{"intro":"Cụ bà được con cháu đưa vào khoa Chấn thương chỉnh hình sau trượt ngã trong nhà tắm 6 giờ, đau háng phải, không đứng dậy được.","place":null,"clock":null,"night":false},"vitals":{"hr":92,"sbp":150,"dbp":84,"rr":20,"temperature_c":36.9,"spo2":96},"history":[{"question":"Bà ngã như thế nào, có ngất trước khi ngã không?","response":"Trượt chân trong nhà tắm, ngã nghiêng sang phải; không choáng váng, không mất ý thức."},{"question":"Đau ở đâu, có đứng dậy hoặc bước đi được không?","response":"Đau sâu vùng bẹn và háng phải, tăng khi cử động, không đứng dậy được."},{"question":"Trước khi ngã bà đi lại ra sao?","response":"Tự đi lại trong nhà, ra ngoài cần người đỡ; không dùng dụng cụ; sinh hoạt cơ bản tự làm."},{"question":"Có đập đầu, đau cổ, đau lưng hoặc đau ở nơi khác không?","response":"Không đập đầu; hơi đau cổ tay phải nhưng nhẹ."},{"question":"Bệnh nền và thuốc đang dùng?","response":"Tăng huyết áp 15 năm (amlodipin), đái tháo đường típ 2 (metformin); biết loãng xương nhưng chưa điều trị."},{"question":"Có dùng thuốc chống đông hoặc dị ứng thuốc không?","response":"Không dùng chống đông; không dị ứng."},{"question":"Trí nhớ và ăn uống gần đây thế nào?","response":"Tỉnh táo, nhớ tốt; ăn sáng cách đây 8 giờ."}],"examination":[{"group":"K","item":"Quan sát và đo chiều dài chi","finding":"Chân phải ngắn khoảng 2 cm, xoay ngoài, bàn chân đổ ra ngoài; vùng bẹn sưng nhẹ, bầm ít."},{"group":"K","item":"Sờ và nghiệm pháp vận động háng","finding":"Ấn đau nếp bẹn phải; đau tăng khi xoay hoặc gõ dọc trục gót; không nhấc được gót khỏi giường."},{"group":"K","item":"Tuần hoàn và thần kinh chi dưới phải","finding":"Mạch mu chân rõ, đầu chi ấm, cảm giác và vận động ngón chân bình thường."},{"group":"K","item":"Khám toàn thân và tìm tổn thương phối hợp","finding":"Tim đều, phổi không ran; cột sống cổ, lưng không đau chói; cổ tay phải đau nhẹ, không biến dạng."},{"group":"K","item":"Da vùng cùng cụt và gót","finding":"Da nguyên vẹn."}],"investigations":[{"name":"X-quang khung chậu thẳng và háng phải thẳng, nghiêng","duration_minutes":10,"result":"Gãy cổ xương đùi phải dưới chỏm, di lệch nhiều (Garden IV), mất đường Shenton, xương thưa rõ."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang 90 lần/phút, không dấu thiếu máu cục bộ cũ hay mới."},{"name":"Công thức máu, nhóm máu, đông máu","duration_minutes":10,"result":"Hb 11,6 g/dL; tiểu cầu 220 G/L; INR 1,0; có nhóm máu."},{"name":"Ure, creatinin, điện giải đồ, đường huyết","duration_minutes":10,"result":"Creatinin 92 µmol/L; Na 137, K 4,2 mmol/L; đường huyết 9,1 mmol/L."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Tim phổi bình thường."},{"name":"Đo mật độ xương DEXA trước mổ để quyết định thời điểm phẫu thuật","duration_minutes":10,"result":"Không cần làm trước mổ, làm chậm điều trị; việc đánh giá loãng xương thực hiện sau."}],"choices":{"diagnosis":{"ydx":["Gãy mấu chuyển lớn xương đùi phải ổn định","Trật khớp háng phải ra sau","Viêm khớp háng nhiễm khuẩn cấp","Gãy cổ xương đùi phải di lệch (Garden IV) trên nền loãng xương"]},"actions":["Thay khớp háng bán phần, kháng sinh dự phòng trước rạch da, phòng huyết khối bằng heparin trọng lượng phân tử thấp","Cho ngồi dậy, tập đi ngay ngày đầu sau mổ, phục hồi chức năng, điều trị loãng xương và phòng ngã","Cho nằm bất động nhiều tuần tại giường để chờ giảm đau rồi mới tính mổ","Giảm đau sớm bằng paracetamol, phong bế thần kinh vùng và bất động chi, tránh NSAID","Hội chẩn gây mê và nội khoa, tối ưu huyết áp, đường huyết, dịch","Chụp X-quang khung chậu, háng phải, làm điện tâm đồ và xét nghiệm tiền phẫu","Cho về nhà dùng thuốc giảm đau, hẹn tái khám sau một tháng","Đánh giá nguyên nhân ngã (ngất, loạn nhịp, hạ đường huyết) và tìm tổn thương phối hợp"]}}'::jsonb,
  '9ca371aca92ed7c5d021698a8b7698eacd089693d61aed2e81767084753fa4c6'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
