values (
  'ngoai-chan-thuong-002',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-002-1","resource_type":"other","source":"Bộ Y tế: Hướng dẫn chẩn đoán và điều trị loãng xương (cập nhật).","title":"Bộ Y tế: Hướng dẫn chẩn đoán và điều trị loãng xương (cập nhật).","organization":null,"year_version":null,"citation":"Bộ Y tế: Hướng dẫn chẩn đoán và điều trị loãng xương (cập nhật).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-002-2","resource_type":"textbook","source":"Giáo trình Chấn thương chỉnh hình, Đại học Y Hà Nội: bài Gãy cổ xương đùi.","title":"Giáo trình Chấn thương chỉnh hình, Đại học Y Hà Nội: bài Gãy cổ xương đùi.","organization":null,"year_version":null,"citation":"Giáo trình Chấn thương chỉnh hình, Đại học Y Hà Nội: bài Gãy cổ xương đùi.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-nice-cg124","resource_type":"other","source":"https://www.nice.org.uk/guidance/cg124","title":"NICE guideline NG124, Hip fracture: management, 2023.","organization":null,"year_version":null,"citation":"NICE guideline NG124, Hip fracture: management, 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-002-4","resource_type":"other","source":"AAOS Management of Hip Fractures in Older Adults, 2021.","title":"AAOS Management of Hip Fractures in Older Adults, 2021.","organization":null,"year_version":null,"citation":"AAOS Management of Hip Fractures in Older Adults, 2021.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Gãy mấu chuyển lớn xương đùi phải ổn định","credit":"none"},{"text":"Trật khớp háng phải ra sau","credit":"none"},{"text":"Gãy cổ xương đùi phải di lệch (Garden IV) trên nền loãng xương","credit":"full"},{"text":"Viêm khớp háng nhiễm khuẩn cấp","credit":"none"}]},"action_options":[{"text":"Đánh giá nguyên nhân ngã (ngất, loạn nhịp, hạ đường huyết) và tìm tổn thương phối hợp","time_minutes":2,"grade":"critical","rationale":"Ngã ở người già có thể do bệnh nội khoa; bỏ sót làm tăng nguy cơ biến chứng và tử vong."},{"text":"Giảm đau sớm bằng paracetamol, phong bế thần kinh vùng và bất động chi, tránh NSAID","time_minutes":2,"grade":"critical","rationale":"Chức năng thận giảm theo tuổi, lại có tăng huyết áp; giảm đau tốt giúp hạn chế sảng và suy hô hấp."},{"text":"Chụp X-quang khung chậu, háng phải, làm điện tâm đồ và xét nghiệm tiền phẫu","time_minutes":2,"grade":"recommended","rationale":"Xác định loại gãy, phân độ Garden và đánh giá nguy cơ gây mê."},{"text":"Hội chẩn gây mê và nội khoa, tối ưu huyết áp, đường huyết, dịch","time_minutes":3,"grade":"recommended","rationale":"Giữ thời gian chờ mổ ngắn, không trì hoãn chỉ để hoàn hảo hóa số liệu."},{"text":"Thay khớp háng bán phần, kháng sinh dự phòng trước rạch da, phòng huyết khối bằng heparin trọng lượng phân tử thấp","time_minutes":3,"grade":"recommended","rationale":"Gãy di lệch ở người trên 75 tuổi, đi lại hạn chế: thay khớp cho phép chịu lực sớm, ít mổ lại hơn kết hợp xương."},{"text":"Cho ngồi dậy, tập đi ngay ngày đầu sau mổ, phục hồi chức năng, điều trị loãng xương và phòng ngã","time_minutes":2,"grade":"recommended","rationale":"Vận động sớm giảm viêm phổi, loét tỳ đè, huyết khối."},{"text":"Cho nằm bất động nhiều tuần tại giường để chờ giảm đau rồi mới tính mổ","time_minutes":0,"grade":"harmful","rationale":"Bất động kéo dài gây viêm phổi, loét tỳ đè, huyết khối, suy kiệt."},{"text":"Cho về nhà dùng thuốc giảm đau, hẹn tái khám sau một tháng","time_minutes":0,"grade":"harmful","rationale":"Gãy cổ xương đùi di lệch không tự liền, biến chứng nặng và tử vong cao nếu không mổ."}],"teaching_explanation":"Gãy cổ xương đùi di lệch ở người trên 75 tuổi là cấp cứu chương trình: giảm đau tốt, tối ưu nội khoa nhanh và mổ trong 24 đến 48 giờ. Thay khớp bán phần thường là lựa chọn phù hợp khi người bệnh đi lại hạn chế; vận động sớm và điều trị loãng xương quyết định tiên lượng."}'::jsonb,
  'bfb3037dbe8bb82afd425fce8407dbc2845f9ddcdf53fc14aa2fc3384266c616'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-chan-thuong-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Ngã xe, cẳng tay trái biến dạng, sưng đau","setting":"giuong","level":"Dễ","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":28,"sex":"nam","patient_label":"Anh H. V. D."},"presentation":{"intro":"Nam thanh niên đến khoa Chấn thương chỉnh hình sau ngã xe máy 2 giờ, tay trái chống xuống đất, cẳng tay biến dạng, sưng đau nhiều.","place":null,"clock":null,"night":false},"vitals":{"hr":94,"sbp":124,"dbp":78,"rr":18,"temperature_c":37,"spo2":99},"history":[{"question":"Tai nạn xảy ra thế nào, tay nào chống xuống đất?","response":"Ngã xe máy cách 2 giờ, chống tay trái xuống mặt đường rồi ngã nghiêng."},{"question":"Đau ở đâu, có cử động được cổ tay, ngón tay không?","response":"Đau dữ dội giữa cẳng tay trái, cử động ngón tay được nhưng đau tăng."},{"question":"Có tê bì hoặc lạnh ngón tay không?","response":"Hơi tê đầu ngón nhưng cảm giác còn; ngón tay không lạnh."},{"question":"Có vết thương hở hoặc chảy máu tại chỗ đau không?","response":"Da nguyên vẹn, chỉ có trầy xước ngoài da khuỷu tay."},{"question":"Có chấn thương đầu, ngực, bụng hoặc nơi khác không?","response":"Không đập đầu, không đau nơi nào khác ngoài cẳng tay."},{"question":"Tiền sử bệnh, dị ứng, thuốc đang dùng?","response":"Khỏe mạnh, không dị ứng, không dùng thuốc."},{"question":"Lần ăn uống gần nhất?","response":"Ăn trưa cách đây 3 giờ."}],"examination":[{"group":"K","item":"Quan sát cẳng tay trái","finding":"Sưng nề, biến dạng gập góc ở 1/3 giữa, da nguyên vẹn, bầm tím nhẹ."},{"group":"K","item":"Sờ nắn và ép dọc trục","finding":"Điểm đau chói 1/3 giữa cẳng tay, có tiếng lạo xạo xương; không có vết thương thông với ổ gãy."},{"group":"K","item":"Mạch, đầu chi, thần kinh","finding":"Mạch quay rõ, thời gian đầy mao mạch 2 giây, cảm giác ngón 1 đến 3 bình thường, gập ngón cái được."},{"group":"K","item":"Khoang cẳng tay (dấu hiệu chèn ép khoang)","finding":"Khoang gấp căng nhưng còn mềm; duỗi thụ động ngón tay chỉ đau ở ổ gãy, không đau tăng đặc biệt."},{"group":"K","item":"Khuỷu và cổ tay hai bên","finding":"Không đau, cử động đủ biên độ, không biến dạng."}],"investigations":[{"name":"X-quang cẳng tay trái thẳng và nghiêng, bao gồm khuỷu và cổ tay","duration_minutes":10,"result":"Gãy 1/3 giữa xương quay và 1/3 giữa xương trụ, gập góc 25 độ, chồng ngắn 10 mm; khớp quay trụ gần và xa không trật."},{"name":"Công thức máu, nhóm máu","duration_minutes":10,"result":"Hb 14,8 g/dL; tiểu cầu 260 G/L."},{"name":"Điện giải đồ, chức năng thận, đường huyết","duration_minutes":10,"result":"Trong giới hạn bình thường."},{"name":"Điện tâm đồ tiền phẫu","duration_minutes":10,"result":"Nhịp xoang 90 lần/phút."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Không tổn thương."},{"name":"Chụp mạch máu cản quang thường quy khi mạch quay bắt rõ","duration_minutes":10,"result":"Không có chỉ định; làm chậm điều trị và có nguy cơ."}],"choices":{"diagnosis":{"ydx":["Gãy kín đầu dưới xương quay kiểu Colles","Bong gân độ III cổ tay trái","Gãy Monteggia (gãy xương trụ kèm trật chỏm quay)","Gãy kín hai xương cẳng tay trái 1/3 giữa, di lệch, chưa có biến chứng mạch, thần kinh hay chèn ép khoang"]},"actions":["Chụp X-quang cẳng tay hai tư thế bao gồm khuỷu và cổ tay","Nắn mạnh nhiều lần không gây mê rồi bó bột tròn kín ngay","Mổ kết hợp xương bằng nẹp vít xương quay và xương trụ, kháng sinh dự phòng","Nẹp bất động tạm từ cánh tay đến bàn tay, nâng cao chi, giảm đau","Nhịn ăn, hội chẩn gây mê, chuẩn bị mổ sớm","Cho về nhà, dùng giảm đau, hẹn tái khám sau 1 tuần mà không bất động","Đánh giá và ghi nhận mạch, cảm giác, vận động, đau khi duỗi thụ động ngón tay mỗi 1 đến 2 giờ","Sau mổ: nâng cao chi, tập ngón tay ngay, tập khuỷu và xoay sớm, tái khám X-quang theo lịch"]}}'::jsonb,
  '0f523cb7fa85ef3ec21e381063934c4a04cd25ebf0622772714765fc5d8fd70a'
)
on conflict (case_id) do update set
