  'ngoai-chan-thuong-003',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-003-1","resource_type":"textbook","source":"Giáo trình Chấn thương chỉnh hình, Đại học Y Hà Nội: bài Gãy hai xương cẳng tay.","title":"Giáo trình Chấn thương chỉnh hình, Đại học Y Hà Nội: bài Gãy hai xương cẳng tay.","organization":null,"year_version":null,"citation":"Giáo trình Chấn thương chỉnh hình, Đại học Y Hà Nội: bài Gãy hai xương cẳng tay.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-003-2","resource_type":"textbook","source":"Rockwood and Green''s Fractures in Adults, 9th edition, 2019: chương Fractures of the shafts of the radius and ulna.","title":"Rockwood and Green''s Fractures in Adults, 9th edition, 2019: chương Fractures of the shafts of the radius and ulna.","organization":null,"year_version":null,"citation":"Rockwood and Green''s Fractures in Adults, 9th edition, 2019: chương Fractures of the shafts of the radius and ulna.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-003-3","resource_type":"other","source":"ATLS 10th edition, American College of Surgeons, 2018: phần Chấn thương cơ xương khớp.","title":"ATLS 10th edition, American College of Surgeons, 2018: phần Chấn thương cơ xương khớp.","organization":null,"year_version":null,"citation":"ATLS 10th edition, American College of Surgeons, 2018: phần Chấn thương cơ xương khớp.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Gãy kín đầu dưới xương quay kiểu Colles","credit":"none"},{"text":"Gãy Monteggia (gãy xương trụ kèm trật chỏm quay)","credit":"none"},{"text":"Bong gân độ III cổ tay trái","credit":"none"},{"text":"Gãy kín hai xương cẳng tay trái 1/3 giữa, di lệch, chưa có biến chứng mạch, thần kinh hay chèn ép khoang","credit":"full"}]},"action_options":[{"text":"Nẹp bất động tạm từ cánh tay đến bàn tay, nâng cao chi, giảm đau","time_minutes":2,"grade":"critical","rationale":"Giảm đau, hạn chế di lệch thêm và phù nề trước khi mổ."},{"text":"Đánh giá và ghi nhận mạch, cảm giác, vận động, đau khi duỗi thụ động ngón tay mỗi 1 đến 2 giờ","time_minutes":2,"grade":"critical","rationale":"Chèn ép khoang là biến chứng hay bị bỏ sót; phát hiện sớm tránh hoại tử cơ."},{"text":"Chụp X-quang cẳng tay hai tư thế bao gồm khuỷu và cổ tay","time_minutes":2,"grade":"recommended","rationale":"Loại trừ tổn thương Monteggia, Galeazzi."},{"text":"Nhịn ăn, hội chẩn gây mê, chuẩn bị mổ sớm","time_minutes":2,"grade":"recommended","rationale":"Gãy hai xương ở người lớn là gãy không vững, thường cần mổ."},{"text":"Mổ kết hợp xương bằng nẹp vít xương quay và xương trụ, kháng sinh dự phòng","time_minutes":3,"grade":"recommended","rationale":"Phục hồi chiều dài, độ cong và xoay cẳng tay, cho phép tập sớm."},{"text":"Sau mổ: nâng cao chi, tập ngón tay ngay, tập khuỷu và xoay sớm, tái khám X-quang theo lịch","time_minutes":2,"grade":"recommended","rationale":"Phòng cứng khớp, hạn chế xoay cẳng tay."},{"text":"Nắn mạnh nhiều lần không gây mê rồi bó bột tròn kín ngay","time_minutes":0,"grade":"harmful","rationale":"Gây đau, tăng phù nề, nguy cơ chèn ép khoang; gãy hai xương hiếm giữ được đường nắn kín."},{"text":"Cho về nhà, dùng giảm đau, hẹn tái khám sau 1 tuần mà không bất động","time_minutes":0,"grade":"harmful","rationale":"Di lệch tăng, tổn thương mô mềm và mạch thần kinh."}],"teaching_explanation":"Gãy hai xương cẳng tay ở người lớn là gãy không vững, điều trị chuẩn là mổ kết hợp xương nẹp vít. Luôn kiểm tra khuỷu và cổ tay để không bỏ sót Monteggia, Galeazzi, và theo dõi sát dấu hiệu chèn ép khoang."}'::jsonb,
  'b700e04849e1508e10dd0d80167ac3de04831dc5ecc9b8b9f09230d75e3212b8'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-chan-thuong-004',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Ngã giàn giáo, đau ngực trái, khó thở, vã mồ hôi","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":34,"sex":"nam","patient_label":"Anh P. Q. K."},"presentation":{"intro":"Nam công nhân xây dựng được đưa vào phòng cấp cứu 40 phút sau khi ngã giàn giáo cao khoảng 4 m, đập ngực trái xuống nền, khó thở và da lạnh.","place":null,"clock":null,"night":false},"vitals":{"hr":118,"sbp":92,"dbp":58,"rr":30,"temperature_c":36.5,"spo2":90},"history":[{"question":"Cơ chế chấn thương là gì, ngã từ độ cao bao nhiêu?","response":"Ngã giàn giáo khoảng 4 m, đập ngực trái vào cạnh sắt rồi xuống nền."},{"question":"Đau và khó thở ra sao?","response":"Đau ngực trái nhiều, thở nông, không nằm ngửa được, nói từng câu ngắn."},{"question":"Có ho ra máu, đau bụng, đau vai trái hoặc đau chỗ khác không?","response":"Ho ít đờm lẫn máu; đau nhẹ bụng trên trái; chưa than đau cổ."},{"question":"Có mất ý thức sau ngã không?","response":"Không mất ý thức, tỉnh táo."},{"question":"Có bệnh phổi, tim hoặc dùng thuốc chống đông không?","response":"Hút thuốc lá 10 năm; không bệnh tim, không dùng chống đông."},{"question":"Dị ứng thuốc, tiêm phòng uốn ván?","response":"Không dị ứng; chưa nhớ tiêm phòng uốn ván."},{"question":"Lần ăn gần nhất?","response":"Ăn trưa cách đây 3 giờ."}],"examination":[{"group":"K","item":"Đường thở, hô hấp và quan sát lồng ngực","finding":"Nói được từng câu ngắn, thở nhanh nông, bầm tím và lõm vùng ngực trái, không có vết thương hở, khí quản ở giữa."},{"group":"K","item":"Gõ và nghe phổi","finding":"Gõ đục nửa dưới phổi trái, rì rào phế nang giảm hẳn bên trái; phổi phải bình thường."},{"group":"K","item":"Tuần hoàn","finding":"Mạch nhanh nhẹ, chi lạnh, da tái vã mồ hôi, thời gian đầy mao mạch 4 giây; tĩnh mạch cổ xẹp."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, ấn đau nhẹ hạ sườn trái, chưa phản ứng thành bụng."},{"group":"K","item":"Khám cổ và khung chậu","finding":"Cột sống cổ không điểm đau; khung chậu vững."}],"investigations":[{"name":"Siêu âm eFAST tại giường","duration_minutes":15,"result":"Có dịch khoang màng phổi trái; ổ bụng và màng ngoài tim không thấy dịch tự do."},{"name":"X-quang ngực thẳng tại giường","duration_minutes":10,"result":"Mờ nửa dưới phổi trái, mất góc sườn hoành, gãy cung sau xương sườn 6 đến 8 trái, không tràn khí rõ."},{"name":"Công thức máu, nhóm máu, đông máu, khí máu","duration_minutes":10,"result":"Hb 8,9 g/dL; lactate 4,2 mmol/L; pH 7,30; tiểu cầu 190 G/L; INR 1,1; đã chuẩn bị máu."},{"name":"Dẫn lưu màng phổi liên sườn 5 đường nách giữa: lượng dịch dẫn lưu","duration_minutes":10,"result":"Ra ngay 1.600 mL máu đỏ tươi trong 15 phút đầu, vẫn chảy liên tục."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp nhanh xoang 118 lần/phút, không dấu thiếu máu cục bộ."},{"name":"CT ngực có cản quang trước khi dẫn lưu khi huyết áp 92/58 mmHg","duration_minutes":40,"result":"Không an toàn; chậm hồi sức và dẫn lưu cấp cứu."}],"choices":{"diagnosis":{"ydx":["Chèn ép tim cấp do máu màng ngoài tim","Tràn khí màng phổi áp lực trái","Tràn máu màng phổi trái lượng nhiều do chấn thương ngực kín, gãy xương sườn 6 đến 8, sốc mất máu độ III","Vỡ cơ hoành trái đơn thuần"]},"actions":["Đặt dẫn lưu màng phổi trái cỡ lớn ngay, không chờ thêm xét nghiệm","Hội chẩn ngoại lồng ngực và chuyển mổ mở ngực cấp cứu khi dẫn lưu ra từ 1.500 mL ngay","Làm eFAST và X-quang ngực tại giường trong lúc hồi sức","Truyền máu sớm (nhóm O hoặc cùng nhóm), hạn chế tinh thể, giữ ấm","Chuyển đi chụp CT ngực khi huyết áp còn 92/58 mmHg và đang sốc","Sau mổ: giảm đau đa mô thức, vật lý trị liệu hô hấp, rút dẫn lưu khi dịch dưới 200 mL mỗi 24 giờ, phòng uốn ván","Thở oxy lưu lượng cao, đặt hai đường truyền lớn, lấy máu xét nghiệm và nhóm máu","Truyền 3 đến 4 lít tinh thể nhanh để đưa huyết áp về bình thường"]}}'::jsonb,
  '0ca32fd89762bd3a459cc76e153c8158d0ba753e54c26ed5fd5e5021c3287282'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

