  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-004-1","resource_type":"other","source":"ATLS 10th edition, American College of Surgeons, 2018: chương Thoracic Trauma.","title":"ATLS 10th edition, American College of Surgeons, 2018: chương Thoracic Trauma.","organization":null,"year_version":null,"citation":"ATLS 10th edition, American College of Surgeons, 2018: chương Thoracic Trauma.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-004-2","resource_type":"textbook","source":"Giáo trình Ngoại bệnh lý, Đại học Y Dược TP.HCM: bài Chấn thương ngực.","title":"Giáo trình Ngoại bệnh lý, Đại học Y Dược TP.HCM: bài Chấn thương ngực.","organization":null,"year_version":null,"citation":"Giáo trình Ngoại bệnh lý, Đại học Y Dược TP.HCM: bài Chấn thương ngực.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-004-3","resource_type":"other","source":"Bộ Y tế: Hướng dẫn quy trình kỹ thuật chuyên ngành ngoại khoa (dẫn lưu màng phổi).","title":"Bộ Y tế: Hướng dẫn quy trình kỹ thuật chuyên ngành ngoại khoa (dẫn lưu màng phổi).","organization":null,"year_version":null,"citation":"Bộ Y tế: Hướng dẫn quy trình kỹ thuật chuyên ngành ngoại khoa (dẫn lưu màng phổi).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tràn khí màng phổi áp lực trái","credit":"none"},{"text":"Tràn máu màng phổi trái lượng nhiều do chấn thương ngực kín, gãy xương sườn 6 đến 8, sốc mất máu độ III","credit":"full"},{"text":"Chèn ép tim cấp do máu màng ngoài tim","credit":"none"},{"text":"Vỡ cơ hoành trái đơn thuần","credit":"none"}]},"action_options":[{"text":"Thở oxy lưu lượng cao, đặt hai đường truyền lớn, lấy máu xét nghiệm và nhóm máu","time_minutes":2,"grade":"critical","rationale":"Ưu tiên oxy hóa và tuần hoàn; SpO2 90% và sốc mất máu đồng thời."},{"text":"Đặt dẫn lưu màng phổi trái cỡ lớn ngay, không chờ thêm xét nghiệm","time_minutes":2,"grade":"critical","rationale":"Dẫn lưu vừa điều trị vừa định lượng chảy máu; tràn máu lượng nhiều gây suy hô hấp và sốc."},{"text":"Truyền máu sớm (nhóm O hoặc cùng nhóm), hạn chế tinh thể, giữ ấm","time_minutes":2,"grade":"critical","rationale":"Mất máu là chính; truyền ồ ạt tinh thể gây loãng máu, rối loạn đông máu."},{"text":"Làm eFAST và X-quang ngực tại giường trong lúc hồi sức","time_minutes":2,"grade":"critical","rationale":"Phát hiện dịch màng phổi, tràn khí, loại trừ chảy máu bụng hoặc tim."},{"text":"Hội chẩn ngoại lồng ngực và chuyển mổ mở ngực cấp cứu khi dẫn lưu ra từ 1.500 mL ngay","time_minutes":3,"grade":"recommended","rationale":"Chảy máu liên tục sau dẫn lưu là chỉ định mổ cầm máu, không chờ."},{"text":"Sau mổ: giảm đau đa mô thức, vật lý trị liệu hô hấp, rút dẫn lưu khi dịch dưới 200 mL mỗi 24 giờ, phòng uốn ván","time_minutes":2,"grade":"recommended","rationale":"Gãy nhiều xương sườn gây đau hạn chế thông khí; giảm đau tốt phòng viêm phổi và xẹp phổi."},{"text":"Chuyển đi chụp CT ngực khi huyết áp còn 92/58 mmHg và đang sốc","time_minutes":0,"grade":"harmful","rationale":"Đưa người bệnh sốc ra khỏi khu hồi sức làm tăng nguy cơ ngừng tim."},{"text":"Truyền 3 đến 4 lít tinh thể nhanh để đưa huyết áp về bình thường","time_minutes":0,"grade":"harmful","rationale":"Gây loãng máu, hạ thân nhiệt, rối loạn đông máu và tăng chảy máu."}],"teaching_explanation":"Ở người bệnh chấn thương ngực có sốc, giảm thông khí một bên, gõ đục và rì rào phế nang giảm cần nghĩ tới tràn máu màng phổi lớn: đặt dẫn lưu ngay, hồi sức bằng máu. Dẫn lưu ra từ 1.500 mL ngay hoặc chảy liên tục từ 200 mL mỗi giờ là chỉ định mở ngực cầm máu."}'::jsonb,
