insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-chan-thuong-005',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-005","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nổ bếp gas, bỏng lửa diện rộng, khàn tiếng","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":32,"sex":"nam","patient_label":"Anh T. M. H."},"presentation":{"intro":"Nam thanh niên nặng 60 kg được đưa vào phòng cấp cứu 1 giờ sau vụ nổ bếp gas trong nhà kín, bỏng lửa vùng mặt, ngực bụng và hai tay, giọng khàn.","place":null,"clock":null,"night":false},"vitals":{"hr":124,"sbp":104,"dbp":64,"rr":28,"temperature_c":36.2,"spo2":94},"history":[{"question":"Bỏng xảy ra thế nào, trong nhà kín hay ngoài trời?","response":"Nổ bếp gas trong bếp kín, lửa bùng vào người, quần áo bắt cháy; được dập lửa sau khoảng 1 phút."},{"question":"Bỏng cách đây bao lâu, đã sơ cứu gì?","response":"Cách 1 giờ; người nhà dội nước mát và cởi áo, quấn khăn sạch."},{"question":"Có ho, khàn tiếng, khó thở hoặc khạc đờm đen không?","response":"Khàn giọng, ho đờm lẫn bồ hóng, thở nhanh."},{"question":"Có tỉnh táo không, có ngạt khói trong phòng kín không?","response":"Tỉnh, đau đầu; ở trong phòng đầy khói khoảng 2 phút."},{"question":"Có chấn thương kèm theo (ngã, va đập) không?","response":"Bị hất ngã nhưng không đập đầu, không đau cổ, ngực bụng."},{"question":"Bệnh nền, dị ứng, thuốc đang dùng?","response":"Khỏe mạnh, không bệnh nền, không dị ứng."},{"question":"Lần ăn uống gần nhất?","response":"Ăn tối cách 3 giờ."}],"examination":[{"group":"K","item":"Đường thở và vùng mặt cổ","finding":"Khàn tiếng, bồ hóng quanh mũi miệng, lông mũi cháy sém, niêm mạc miệng đỏ phù nhẹ; thở khò khè, không rút lõm ngực."},{"group":"K","item":"Đánh giá diện tích và độ sâu bỏng (quy tắc số 9)","finding":"Thân trước 18%, hai chi trên 18% (cả chu vi), mặt cổ 4%: tổng 40%. Vùng ngực trước và mặt trong cẳng tay có da trắng ngà, mất cảm giác (độ III) khoảng 15%; phần còn lại độ II sâu phồng nước."},{"group":"K","item":"Tuần hoàn chi trên và ngực","finding":"Chi trên phải phù căng, mạch quay yếu, đầu ngón lạnh; chi trên trái mạch quay rõ; ngực bỏng sâu hạn chế giãn nở."},{"group":"K","item":"Tri giác và tuần hoàn toàn thân","finding":"Tỉnh, Glasgow 15; da lạnh ẩm, thời gian đầy mao mạch 3 giây."},{"group":"K","item":"Tìm tổn thương kèm theo","finding":"Cột sống cổ, ngực, bụng và khung chậu không điểm đau; không biến dạng chi."}],"investigations":[{"name":"Khí máu động mạch và COHb","duration_minutes":10,"result":"pH 7,31; lactate 3,4 mmol/L; BE âm 5; COHb 14% (đã thở oxy 100%)."},{"name":"Công thức máu, ure, creatinin, điện giải đồ","duration_minutes":10,"result":"Hb 17,0 g/dL, hematocrit 51% (cô đặc); Na 138, K 4,4 mmol/L; creatinin 88 µmol/L."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp nhanh xoang 120 lần/phút, không dấu thiếu máu cục bộ."},{"name":"X-quang ngực thẳng tại giường","duration_minutes":10,"result":"Chưa thấy tổn thương nhu mô rõ; thường chưa thay đổi sớm trong bỏng hô hấp."},{"name":"Nội soi phế quản ống mềm khi đã bảo đảm đường thở","duration_minutes":20,"result":"Bồ hóng và phù nề niêm mạc thanh môn, khí quản; xác nhận tổn thương hô hấp do hít khói."},{"name":"Cấy vết bỏng ngay khi tiếp nhận để quyết định kháng sinh dự phòng toàn thân","duration_minutes":10,"result":"Không có chỉ định; vết bỏng sớm thường chưa nhiễm khuẩn và kháng sinh dự phòng toàn thân không thường quy."}],"choices":{"diagnosis":{"ydx":["Bỏng lửa nặng khoảng 40% diện tích da (độ II sâu và độ III), nghi bỏng đường hô hấp và ngộ độc CO, đang vào giai đoạn sốc bỏng","Phản vệ độ III","Bỏng độ II nông diện hẹp vùng mặt và ngực","Hội chứng suy hô hấp cấp do viêm phổi hít"]},"actions":["Chuyển trung tâm bỏng; cắt lọc hoại tử sớm và ghép da; nuôi dưỡng tiêu hóa sớm","Đặt hai đường truyền lớn qua da lành, bắt đầu Ringer lactat 400 mL mỗi giờ, đặt thông tiểu theo dõi nước tiểu","Rạch giải áp hoại tử chi trên phải, theo dõi chi trên trái và ngực","Cởi bỏ quần áo, trang sức; che vết bỏng bằng gạc vô khuẩn khô hoặc màng sạch, giữ ấm","Thở oxy 100% và đặt nội khí quản sớm","Giảm đau opioid tĩnh mạch liều nhỏ chia nhiều lần, tiêm phòng uốn ván","Bôi kem đánh răng, nước mắm hoặc mỡ động vật lên vết bỏng rồi băng kín","Hạn chế dịch trong 24 giờ đầu và dùng lợi tiểu sớm để tránh phù phổi","Chườm đá lạnh hoặc ngâm cả người nước đá kéo dài"]}}'::jsonb,
  'c63552336cb0636958f795a3cba55dee9a293dd20ef97aee7e1990bf71f163cc'
)
