values (
  'ngoai-chan-thuong-005',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-005","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-005-1","resource_type":"other","source":"Bộ Y tế: Hướng dẫn chẩn đoán và điều trị bỏng.","title":"Bộ Y tế: Hướng dẫn chẩn đoán và điều trị bỏng.","organization":null,"year_version":null,"citation":"Bộ Y tế: Hướng dẫn chẩn đoán và điều trị bỏng.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-005-2","resource_type":"other","source":"American Burn Association: Advanced Burn Life Support (ABLS) Provider Manual, 2018.","title":"American Burn Association: Advanced Burn Life Support (ABLS) Provider Manual, 2018.","organization":null,"year_version":null,"citation":"American Burn Association: Advanced Burn Life Support (ABLS) Provider Manual, 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-005-3","resource_type":"other","source":"International Society for Burn Injuries: ISBI Practice Guidelines for Burn Care, 2016.","title":"International Society for Burn Injuries: ISBI Practice Guidelines for Burn Care, 2016.","organization":null,"year_version":null,"citation":"International Society for Burn Injuries: ISBI Practice Guidelines for Burn Care, 2016.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-005-4","resource_type":"other","source":"ATLS 10th edition, American College of Surgeons, 2018: chương Thermal Injuries.","title":"ATLS 10th edition, American College of Surgeons, 2018: chương Thermal Injuries.","organization":null,"year_version":null,"citation":"ATLS 10th edition, American College of Surgeons, 2018: chương Thermal Injuries.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Bỏng độ II nông diện hẹp vùng mặt và ngực","credit":"none"},{"text":"Hội chứng suy hô hấp cấp do viêm phổi hít","credit":"none"},{"text":"Phản vệ độ III","credit":"none"},{"text":"Bỏng lửa nặng khoảng 40% diện tích da (độ II sâu và độ III), nghi bỏng đường hô hấp và ngộ độc CO, đang vào giai đoạn sốc bỏng","credit":"full"}]},"action_options":[{"text":"Thở oxy 100% và đặt nội khí quản sớm","time_minutes":2,"grade":"critical","rationale":"Khàn tiếng, bồ hóng, lông mũi cháy sém báo hiệu phù nề đường thở tăng nhanh, đặt muộn có thể không còn khả thi."},{"text":"Đặt hai đường truyền lớn qua da lành, bắt đầu Ringer lactat 400 mL mỗi giờ, đặt thông tiểu theo dõi nước tiểu","time_minutes":2,"grade":"critical","rationale":"Bỏng trên 20% diện tích cần bù dịch sớm; điều chỉnh tốc độ truyền mỗi giờ (khoảng 10 đến 20%, hoặc 1/3 theo JSBI) khi nước tiểu lệch mục tiêu 0,5 mL mỗi kg mỗi giờ."},{"text":"Cởi bỏ quần áo, trang sức; che vết bỏng bằng gạc vô khuẩn khô hoặc màng sạch, giữ ấm","time_minutes":2,"grade":"critical","rationale":"Hạn chế mất nhiệt và nhiễm khuẩn; làm mát kéo dài trên diện rộng gây hạ thân nhiệt."},{"text":"Giảm đau opioid tĩnh mạch liều nhỏ chia nhiều lần, tiêm phòng uốn ván","time_minutes":2,"grade":"critical","rationale":"Bỏng đau dữ dội; tiêm phòng uốn ván là bắt buộc."},{"text":"Rạch giải áp hoại tử chi trên phải, theo dõi chi trên trái và ngực","time_minutes":3,"grade":"recommended","rationale":"Bỏng sâu vòng quanh chi làm chèn ép tuần hoàn; ngực bỏng sâu hạn chế thở."},{"text":"Chuyển trung tâm bỏng; cắt lọc hoại tử sớm và ghép da; nuôi dưỡng tiêu hóa sớm","time_minutes":3,"grade":"recommended","rationale":"Bỏng sâu rộng cần cắt hoại tử sớm; nuôi ăn sớm giảm hồi biến chuyển hóa."},{"text":"Chườm đá lạnh hoặc ngâm cả người nước đá kéo dài","time_minutes":0,"grade":"harmful","rationale":"Gây hạ thân nhiệt, co mạch, làm sâu thêm tổn thương."},{"text":"Bôi kem đánh răng, nước mắm hoặc mỡ động vật lên vết bỏng rồi băng kín","time_minutes":0,"grade":"harmful","rationale":"Nhiễm khuẩn, che lấp đánh giá độ sâu, khó làm sạch."},{"text":"Hạn chế dịch trong 24 giờ đầu và dùng lợi tiểu sớm để tránh phù phổi","time_minutes":0,"grade":"harmful","rationale":"Gây sốc bỏng nặng, thiếu tưới máu, tổn thương thận cấp."}],"teaching_explanation":"Bỏng lửa trong không gian kín kèm khàn tiếng, bồ hóng cần nghĩ ngay bỏng hô hấp và ngộ độc CO: bảo đảm đường thở sớm và oxy 100%. Bù dịch theo công thức khởi đầu rồi chỉnh theo nước tiểu; bỏng sâu vòng quanh chi hoặc ngực cần theo dõi và rạch giải áp."}'::jsonb,
  'f4b643dc6907c70b146f37672f3c1b079142c7f4c3a7fd57574625f8c9314824'
)
