insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-chan-thuong-006',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-006","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đạp phải sắt gỉ, vết rách lòng bàn chân dính bùn đất","setting":"giuong","level":"Dễ","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":45,"sex":"nam","patient_label":"Anh L. V. B."},"presentation":{"intro":"Nam nông dân đến phòng khám ngoại sau 8 giờ vì vết thương lòng bàn chân phải do đạp phải mảnh sắt gỉ ngoài ruộng, chưa đi khám sớm.","place":null,"clock":null,"night":false},"vitals":{"hr":82,"sbp":128,"dbp":80,"rr":18,"temperature_c":36.8,"spo2":99},"history":[{"question":"Vết thương do vật gì, xảy ra khi nào, ở đâu?","response":"Đạp phải mảnh sắt gỉ ngoài ruộng cách đây 8 giờ; chân dính bùn đất, mới rửa qua bằng nước giếng."},{"question":"Đã tiêm phòng uốn ván bao giờ chưa, có nhớ số mũi không?","response":"Không nhớ đã tiêm lần nào, không có sổ tiêm chủng."},{"question":"Có cứng hàm, khó há miệng, đau gáy, co cứng cơ không?","response":"Không; ăn uống nói chuyện bình thường."},{"question":"Vết thương hiện đau, sưng đỏ, chảy mủ hay có mùi hôi không?","response":"Đau nhiều khi đi lại, sưng nhẹ quanh vết, chưa chảy mủ."},{"question":"Có tiền sử dị ứng thuốc hoặc huyết thanh ngựa không?","response":"Chưa từng dị ứng thuốc; chưa từng tiêm huyết thanh."},{"question":"Bệnh nền (đái tháo đường, bệnh mạch máu, suy giảm miễn dịch)?","response":"Không bệnh nền."},{"question":"Có sốt, rét run hay mệt mỏi không?","response":"Không."}],"examination":[{"group":"K","item":"Quan sát và sờ vết thương lòng bàn chân phải","finding":"Vết rách dài 4 cm, sâu 3 cm, bờ dập nát, dính nhiều bùn đất và mảnh sắt gỉ nhỏ; chảy máu ít, quanh vết sưng nhẹ."},{"group":"K","item":"Mạch và thần kinh bàn chân","finding":"Mạch chày sau và mu chân rõ, cảm giác bàn chân còn, cử động các ngón tốt."},{"group":"K","item":"Khám tìm dấu hiệu uốn ván (hàm, cổ, bụng)","finding":"Há miệng được 4 cm, cổ mềm, bụng mềm, không co cứng, không có co giật."},{"group":"K","item":"Dấu hiệu nhiễm khuẩn tại chỗ","finding":"Quanh vết đỏ nhẹ dưới 1 cm, không có mủ, không có tiếng lép bép dưới da, không hạch bẹn."},{"group":"K","item":"Khám toàn thân","finding":"Tỉnh táo, mạch 82, không sốt."}],"investigations":[{"name":"X-quang bàn chân phải thẳng, nghiêng","duration_minutes":10,"result":"Có dị vật kim loại dài khoảng 5 mm trong phần mềm lòng bàn chân, không gãy xương."},{"name":"Đường huyết mao mạch","duration_minutes":10,"result":"5,6 mmol/L."},{"name":"Công thức máu","duration_minutes":10,"result":"Bạch cầu 8,9 G/L; Hb 14,3 g/dL."},{"name":"Thử phản ứng da với huyết thanh kháng độc tố uốn ván","duration_minutes":10,"result":"Âm tính."},{"name":"Định lượng kháng thể kháng độc tố uốn ván trong máu để quyết định có tiêm hay không","duration_minutes":10,"result":"Không cần chờ kết quả; làm chậm dự phòng khi nguy cơ cao."}],"choices":{"diagnosis":{"ydx":["Vết thương phần mềm bàn chân phải dập nát, nhiễm bẩn, nguy cơ cao uốn ván, tiền sử tiêm phòng không rõ, chưa có triệu chứng uốn ván","Viêm mô hoại tử đã hình thành","Vết thương sạch, nhỏ, nguy cơ uốn ván thấp","Uốn ván toàn thân giai đoạn khởi phát"]},"actions":["Hẹn mũi vắc xin thứ hai sau 4 tuần, mũi thứ ba sau 6 đến 12 tháng; dặn quay lại ngay nếu cứng hàm, đau cơ, sốt hoặc vết thương sưng đau tăng","Rửa nhiều nước muối sinh lý hoặc nước sạch, cắt lọc mô dập nát, lấy dị vật, để hở","Khâu kín ngay vết thương bẩn bờ dập rồi bó chặt","Thử phản ứng da trước khi tiêm huyết thanh kháng độc tố, chuẩn bị xử trí phản vệ","Kháng sinh theo kinh nghiệm cho vết thương bẩn (như amoxicillin kết hợp clavulanat) trong 5 đến 7 ngày","Đắp tro bếp hoặc lá cây lên vết thương để cầm máu","Tiêm kháng độc tố uốn ván và vắc xin hấp phụ uốn ván 0,5 mL ở hai vị trí khác nhau","Băng vô khuẩn, hẹn thay băng sau 48 giờ, khâu thì đầu muộn khi sạch nếu cần","Chỉ tiêm vắc xin mà không tiêm kháng độc tố vì ngại tiêm hai mũi"]}}'::jsonb,
  '8d4ff6413559172197b0ec38a9d91c6a34a24e6c01b7ce6975dc3ac8839bf5d0'
)
