  'ngoai-chan-thuong-006',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-006","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-006-1","resource_type":"other","source":"Bộ Y tế: Hướng dẫn chẩn đoán và điều trị bệnh uốn ván; Chương trình tiêm chủng mở rộng quốc gia.","title":"Bộ Y tế: Hướng dẫn chẩn đoán và điều trị bệnh uốn ván; Chương trình tiêm chủng mở rộng quốc gia.","organization":null,"year_version":null,"citation":"Bộ Y tế: Hướng dẫn chẩn đoán và điều trị bệnh uốn ván; Chương trình tiêm chủng mở rộng quốc gia.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-who-tetanus-2017","resource_type":"guideline","source":"https://www.who.int/publications/i/item/WHO-WER9206","title":"WHO: Tetanus vaccines, position paper, Weekly Epidemiological Record, 2017.","organization":null,"year_version":null,"citation":"WHO: Tetanus vaccines, position paper, Weekly Epidemiological Record, 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-006-3","resource_type":"other","source":"CDC: Updated Recommendations for Use of Tetanus Toxoid, Reduced Diphtheria Toxoid, and Acellular Pertussis Vaccine (MMWR 2018) và hướng dẫn xử trí vết thương.","title":"CDC: Updated Recommendations for Use of Tetanus Toxoid, Reduced Diphtheria Toxoid, and Acellular Pertussis Vaccine (MMWR 2018) và hướng dẫn xử trí vết thương.","organization":null,"year_version":null,"citation":"CDC: Updated Recommendations for Use of Tetanus Toxoid, Reduced Diphtheria Toxoid, and Acellular Pertussis Vaccine (MMWR 2018) và hướng dẫn xử trí vết thương.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-006-4","resource_type":"textbook","source":"Giáo trình Ngoại bệnh lý, Đại học Y Hà Nội: bài Vết thương phần mềm.","title":"Giáo trình Ngoại bệnh lý, Đại học Y Hà Nội: bài Vết thương phần mềm.","organization":null,"year_version":null,"citation":"Giáo trình Ngoại bệnh lý, Đại học Y Hà Nội: bài Vết thương phần mềm.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Vết thương sạch, nhỏ, nguy cơ uốn ván thấp","credit":"none"},{"text":"Uốn ván toàn thân giai đoạn khởi phát","credit":"none"},{"text":"Vết thương phần mềm bàn chân phải dập nát, nhiễm bẩn, nguy cơ cao uốn ván, tiền sử tiêm phòng không rõ, chưa có triệu chứng uốn ván","credit":"full"},{"text":"Viêm mô hoại tử đã hình thành","credit":"none"}]},"action_options":[{"text":"Rửa nhiều nước muối sinh lý hoặc nước sạch, cắt lọc mô dập nát, lấy dị vật, để hở","time_minutes":2,"grade":"critical","rationale":"Vết thương bẩn, dập, sâu, dị vật là môi trường kỵ khí cho Clostridium tetani; làm sạch và cắt lọc là biện pháp quan trọng nhất."},{"text":"Tiêm kháng độc tố uốn ván và vắc xin hấp phụ uốn ván 0,5 mL ở hai vị trí khác nhau","time_minutes":2,"grade":"critical","rationale":"Tiền sử không rõ và vết thương nguy cơ cao cần cả miễn dịch thụ động và chủ động."},{"text":"Thử phản ứng da trước khi tiêm huyết thanh kháng độc tố, chuẩn bị xử trí phản vệ","time_minutes":2,"grade":"recommended","rationale":"Huyết thanh nguồn gốc ngựa có thể gây phản vệ."},{"text":"Kháng sinh theo kinh nghiệm cho vết thương bẩn (như amoxicillin kết hợp clavulanat) trong 5 đến 7 ngày","time_minutes":2,"grade":"recommended","rationale":"Nguy cơ nhiễm khuẩn phối hợp do bùn đất."},{"text":"Băng vô khuẩn, hẹn thay băng sau 48 giờ, khâu thì đầu muộn khi sạch nếu cần","time_minutes":2,"grade":"recommended","rationale":"Vết thương nhiễm bẩn không khâu kín ban đầu."},{"text":"Hẹn mũi vắc xin thứ hai sau 4 tuần, mũi thứ ba sau 6 đến 12 tháng; dặn quay lại ngay nếu cứng hàm, đau cơ, sốt hoặc vết thương sưng đau tăng","time_minutes":2,"grade":"recommended","rationale":"Hoàn thành lịch tiêm tạo miễn dịch lâu dài; phát hiện sớm biến chứng."},{"text":"Khâu kín ngay vết thương bẩn bờ dập rồi bó chặt","time_minutes":0,"grade":"harmful","rationale":"Nhốt vi khuẩn kỵ khí, tăng nguy cơ uốn ván và hoại thư sinh hơi."},{"text":"Chỉ tiêm vắc xin mà không tiêm kháng độc tố vì ngại tiêm hai mũi","time_minutes":0,"grade":"harmful","rationale":"Vắc xin cần nhiều ngày mới tạo kháng thể; không bảo vệ ngay trong thời gian ủ bệnh."},{"text":"Đắp tro bếp hoặc lá cây lên vết thương để cầm máu","time_minutes":0,"grade":"harmful","rationale":"Đưa thêm vi khuẩn và bào tử vào vết thương."}],"teaching_explanation":"Vết thương bẩn, dập, có dị vật và tiền sử tiêm phòng không rõ là nguy cơ cao uốn ván: ngoài làm sạch và cắt lọc, cần tiêm đồng thời kháng độc tố và vắc xin ở hai vị trí khác nhau. Luôn hẹn tiêm đủ mũi và dặn dấu hiệu cần quay lại."}'::jsonb,
  'ad9b0f718ce5a9a361b8776cfcc51adf38687b5a47ed8c885d557c00c3d72ec6'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-chan-thuong-007',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-007","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Xe tải đè, đau bụng dưới, huyết áp 82/48","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":26,"sex":"nữ","patient_label":"Chị V. T. N."},"presentation":{"intro":"Nữ công nhân được đưa vào phòng cấp cứu 50 phút sau tai nạn giao thông, bị xe tải đè lên vùng chậu, đau bụng dưới dữ dội, lạnh, huyết áp thấp.","place":null,"clock":null,"night":false},"vitals":{"hr":128,"sbp":82,"dbp":48,"rr":28,"temperature_c":36,"spo2":94},"history":[{"question":"Cơ chế tai nạn là gì?","response":"Đi xe máy bị xe tải đè lên vùng chậu và bụng dưới khi ngã."},{"question":"Đau ở đâu, có đi tiểu được không?","response":"Đau dữ dội vùng bụng dưới, bẹn hai bên; chưa đi tiểu từ lúc tai nạn."},{"question":"Có máu ở âm hộ, hậu môn hoặc nước tiểu không?","response":"Thấy ít máu ở vùng âm hộ; chưa thấy máu ở hậu môn."},{"question":"Có mất ý thức hoặc đập đầu không?","response":"Tỉnh, không đập đầu."},{"question":"Có thai không, kỳ kinh gần nhất?","response":"Kinh cuối cách 2 tuần, không có thai theo lời kể."},{"question":"Bệnh nền, dị ứng, thuốc đang dùng?","response":"Khỏe mạnh, không dị ứng, không dùng thuốc."},{"question":"Bữa ăn gần nhất?","response":"Ăn sáng cách đây 6 giờ."}],"examination":[{"group":"K","item":"Đánh giá ABCDE","finding":"Đường thở thông, nói được, thở nhanh 28 lần/phút; da tái lạnh ẩm, thời gian đầy mao mạch 4 giây; Glasgow 14."},{"group":"K","item":"Khung chậu: quan sát, ép một lần nhẹ hai cánh chậu","finding":"Bầm máu vùng bẹn đùi hai bên, vùng mu; ép nhẹ một lần hai cánh chậu gây đau dữ dội và cảm giác di động bất thường; chân phải xoay ngoài."},{"group":"K","item":"Bụng","finding":"Chướng nhẹ, đau lan tỏa vùng dưới, không co cứng rõ."},{"group":"K","item":"Âm hộ, niệu đạo, trực tràng","finding":"Ít máu ở âm hộ và lỗ niệu đạo; khám trực tràng không có máu, không có mảnh xương."},{"group":"K","item":"Mạch và thần kinh hai chi dưới","finding":"Mạch bẹn và mu chân hai bên yếu nhưng sờ được; cảm giác và vận động hai chân còn."}],"investigations":[{"name":"Siêu âm eFAST tại giường","duration_minutes":15,"result":"Không thấy dịch tự do ổ bụng, màng ngoài tim và màng phổi hai bên."},{"name":"X-quang ngực thẳng và khung chậu thẳng tại giường","duration_minutes":10,"result":"Phổi bình thường. Khung chậu: giãn khớp mu 3,5 cm, giãn khớp cùng chậu phải, cánh chậu phải mở ra ngoài."},{"name":"Công thức máu, khí máu, lactate, đông máu, nhóm máu","duration_minutes":10,"result":"Hb 7,8 g/dL; lactate 4,6 mmol/L; BE âm 9; INR 1,4; tiểu cầu 130 G/L; đã kích hoạt quy trình truyền máu khối lượng lớn."},{"name":"Đáp ứng với hồi sức ban đầu sau 1.000 mL tinh thể ấm và 2 đơn vị hồng cầu","duration_minutes":10,"result":"Huyết áp lên 90/54 mmHg rồi tụt lại 84/50 sau 20 phút: đáp ứng thoáng qua."},{"name":"Chụp niệu đạo ngược dòng và hình bàng quang khi đã ổn định","duration_minutes":10,"result":"Chưa làm khi còn bất ổn huyết động; lên kế hoạch cùng tiết niệu."},{"name":"CT toàn thân có cản quang ngay khi huyết áp 82/48 mmHg","duration_minutes":40,"result":"Không an toàn khi huyết động chưa ổn định; chỉ làm khi có đáp ứng."}],"choices":{"diagnosis":{"ydx":["Trật khớp mu đơn thuần không chảy máu","Gãy khung chậu mất vững (kiểu ép trước sau) gây chảy máu sau phúc mạc, sốc mất máu độ III đến IV, nghi tổn thương niệu đạo","Vỡ tạng đặc trong ổ bụng đơn thuần","Gãy cổ xương đùi hai bên"]},"actions":["Chưa đặt thông tiểu qua niệu đạo vì có máu ở lỗ niệu đạo; tiết niệu quyết định dẫn lưu trên xương mu hay chụp niệu đạo","Làm eFAST, X-quang ngực, X-quang khung chậu tại giường trong lúc hồi sức","Đai ép hoặc khăn ép khung chậu ngang mấu chuyển lớn, hai chân xoay trong nhẹ và buộc cố định","Truyền tinh thể ồ ạt 4 đến 5 lít để đưa huyết áp về bình thường","Hội chẩn khẩn chấn thương, chỉnh hình, can thiệp mạch và tiết niệu","Hai đường truyền lớn, truyền máu sớm theo tỷ lệ cân bằng, hạn chế tinh thể, giữ ấm, acid tranexamic","Ép bập bênh hai cánh chậu nhiều lần để đánh giá độ vững","Sau cầm máu: hồi sức tích cực, CT khi ổn định, cố định xương chắc chắn, phòng huyết khối, theo dõi biến chứng","Đưa người bệnh đi chụp CT khi chưa ổn định huyết động"]}}'::jsonb,
  '3c6eee1bcae614c22625541c72143620d62ed1dd150598131dc6b5463c1c90c2'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
