values (
  'ngoai-chan-thuong-007',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-007","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-007-1","resource_type":"other","source":"ATLS 10th edition, American College of Surgeons, 2018: chương Shock và Musculoskeletal Trauma.","title":"ATLS 10th edition, American College of Surgeons, 2018: chương Shock và Musculoskeletal Trauma.","organization":null,"year_version":null,"citation":"ATLS 10th edition, American College of Surgeons, 2018: chương Shock và Musculoskeletal Trauma.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-pelvic-wses-2017","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/28115984/","title":"WSES Guidelines: Management of Pelvic Trauma in Hemodynamically Unstable Patients, 2017.","organization":null,"year_version":null,"citation":"WSES Guidelines: Management of Pelvic Trauma in Hemodynamically Unstable Patients, 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-007-3","resource_type":"other","source":"Bộ Y tế: Hướng dẫn quy trình xử trí chấn thương nặng và sốc chấn thương (tài liệu cấp cứu ngoại khoa).","title":"Bộ Y tế: Hướng dẫn quy trình xử trí chấn thương nặng và sốc chấn thương (tài liệu cấp cứu ngoại khoa).","organization":null,"year_version":null,"citation":"Bộ Y tế: Hướng dẫn quy trình xử trí chấn thương nặng và sốc chấn thương (tài liệu cấp cứu ngoại khoa).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-007-4","resource_type":"textbook","source":"Giáo trình Ngoại bệnh lý, Đại học Y Dược TP.HCM: bài Gãy khung chậu.","title":"Giáo trình Ngoại bệnh lý, Đại học Y Dược TP.HCM: bài Gãy khung chậu.","organization":null,"year_version":null,"citation":"Giáo trình Ngoại bệnh lý, Đại học Y Dược TP.HCM: bài Gãy khung chậu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Gãy khung chậu mất vững (kiểu ép trước sau) gây chảy máu sau phúc mạc, sốc mất máu độ III đến IV, nghi tổn thương niệu đạo","credit":"full"},{"text":"Vỡ tạng đặc trong ổ bụng đơn thuần","credit":"none"},{"text":"Gãy cổ xương đùi hai bên","credit":"none"},{"text":"Trật khớp mu đơn thuần không chảy máu","credit":"none"}]},"action_options":[{"text":"Đai ép hoặc khăn ép khung chậu ngang mấu chuyển lớn, hai chân xoay trong nhẹ và buộc cố định","time_minutes":2,"grade":"critical","rationale":"Giảm thể tích khoang chậu, ép tĩnh mạch và mặt xương gãy; làm sớm nhất khi nghi gãy khung chậu có sốc."},{"text":"Hai đường truyền lớn, truyền máu sớm theo tỷ lệ cân bằng, hạn chế tinh thể, giữ ấm, acid tranexamic","time_minutes":2,"grade":"critical","rationale":"Kiểm soát tổn thương: ưu tiên chế phẩm máu, tránh loãng máu và hạ thân nhiệt."},{"text":"Làm eFAST, X-quang ngực, X-quang khung chậu tại giường trong lúc hồi sức","time_minutes":2,"grade":"critical","rationale":"Tìm nguồn mất máu khác (ngực, bụng), xác định loại tổn thương khung chậu."},{"text":"Hội chẩn khẩn chấn thương, chỉnh hình, can thiệp mạch và tiết niệu","time_minutes":3,"grade":"critical","rationale":"Đáp ứng thoáng qua: cần cầm máu bằng nút mạch hoặc nhét gạc tiền phúc mạc, kèm cố định ngoài."},{"text":"Chưa đặt thông tiểu qua niệu đạo vì có máu ở lỗ niệu đạo; tiết niệu quyết định dẫn lưu trên xương mu hay chụp niệu đạo","time_minutes":2,"grade":"recommended","rationale":"Tránh làm rách niệu đạo hoàn toàn."},{"text":"Sau cầm máu: hồi sức tích cực, CT khi ổn định, cố định xương chắc chắn, phòng huyết khối, theo dõi biến chứng","time_minutes":2,"grade":"recommended","rationale":"Phát hiện tổn thương phối hợp và hạn chế biến chứng muộn."},{"text":"Ép bập bênh hai cánh chậu nhiều lần để đánh giá độ vững","time_minutes":0,"grade":"harmful","rationale":"Làm bong cục máu đông, chảy máu nặng thêm."},{"text":"Đưa người bệnh đi chụp CT khi chưa ổn định huyết động","time_minutes":0,"grade":"harmful","rationale":"Tăng nguy cơ ngừng tim ngoài khu hồi sức."},{"text":"Truyền tinh thể ồ ạt 4 đến 5 lít để đưa huyết áp về bình thường","time_minutes":0,"grade":"harmful","rationale":"Gây loãng máu, hạ thân nhiệt, toan máu, rối loạn đông máu."}],"teaching_explanation":"Ở bệnh nhân chấn thương có sốc, khung chậu là một nguồn chảy máu quan trọng: ép khung chậu sớm, truyền máu theo kiểm soát tổn thương và cầm máu sớm bằng nút mạch hoặc nhét gạc tiền phúc mạc. Tránh ép bập bênh nhiều lần, tránh thông tiểu mù khi nghi vỡ niệu đạo, tránh đưa đi CT khi bất ổn."}'::jsonb,
  '2b6a715f80dee1d9b3fbeda66093c0a682f7e20e7443d4035a5e917b6ccf6607'
)
