insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-tiet-nieu-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-tiet-nieu-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau quặn hố thắt lưng phải lan xuống bìu","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":38,"sex":"nam","patient_label":"Anh T.V.H."},"presentation":{"intro":"Người bệnh đến cấp cứu vì cơn đau quặn hố thắt lưng phải dữ dội, vã mồ hôi, buồn nôn.","place":null,"clock":null,"night":false},"vitals":{"hr":98,"sbp":142,"dbp":90,"rr":20,"temperature_c":37.4,"spo2":98},"history":[{"question":"Cơn đau bắt đầu thế nào, lan đi đâu?","response":"Đau đột ngột từ sáng, quặn từng cơn ở hố thắt lưng phải, lan xuống hố chậu và bìu phải, không tìm được tư thế giảm đau."},{"question":"Có sốt, rét run không?","response":"Không sốt, không rét run."},{"question":"Nước tiểu thế nào, có tiểu buốt, tiểu máu không?","response":"Nước tiểu hơi hồng, tiểu hơi buốt; vẫn đi tiểu được."},{"question":"Đã từng có cơn tương tự hoặc đi ra sỏi chưa?","response":"Cách đây hai năm có một cơn nhẹ hơn, tự hết sau uống nhiều nước."},{"question":"Uống nước, chế độ ăn, nghề nghiệp ra sao?","response":"Làm công việc ngoài trời, uống ít nước, hay ăn đồ mặn."},{"question":"Có tiền sử gút, bệnh thận, chỉ có một thận hoặc dùng thuốc chống đông không?","response":"Không; chưa có chẩn đoán gút, không dùng chống đông."},{"question":"Có dị ứng thuốc, bệnh dạ dày không?","response":"Không dị ứng; chưa từng loét dạ dày."}],"examination":[{"group":"K","item":"Tư thế, vẻ mặt","finding":"Vã mồ hôi, vật vã, đi lại liên tục."},{"group":"K","item":"Khám hố thắt lưng","finding":"Rung thận phải (+), ấn góc sườn lưng phải đau; thận không sờ thấy."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, ấn nhẹ hố chậu phải hơi đau, không phản ứng thành bụng, không co cứng."},{"group":"K","item":"Khám bìu và sinh dục","finding":"Tinh hoàn hai bên bình thường, không sưng đau khu trú."},{"group":"K","item":"Sinh hiệu","finding":"Nhiệt 37,4 độ C; mạch nhanh do đau, huyết áp 142/90 mmHg."}],"investigations":[{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Hồng cầu (+++), bạch cầu (+), nitrit âm, pH 5,5."},{"name":"Siêu âm hệ tiết niệu","duration_minutes":15,"result":"Thận phải ứ nước độ 1; không thấy rõ sỏi niệu quản; thận trái bình thường."},{"name":"CT bụng không cản quang liều thấp","duration_minutes":40,"result":"Sỏi 7 mm ở niệu quản phải đoạn 1/3 dưới, thận ứ nước nhẹ, mật độ sỏi 900 HU."},{"name":"Creatinin, ure, điện giải, CRP, bạch cầu máu","duration_minutes":10,"result":"Creatinin 92 µmol/L, ure 5,6 mmol/L, bạch cầu 9,8 G/L, CRP 6 mg/L."},{"name":"Chụp CT có tiêm cản quang toàn ổ bụng thường quy cho mọi cơn đau quặn thận","duration_minutes":40,"result":"Không có chỉ định thường quy; tăng tiếp xúc tia và thuốc cản quang không cần thiết."}],"choices":{"diagnosis":{"ydx":["Viêm đài bể thận cấp có nhiễm khuẩn huyết","Viêm ruột thừa cấp","Xoắn tinh hoàn phải","Cơn đau quặn thận phải do sỏi niệu quản 1/3 dưới, ứ nước độ 1, chưa nhiễm trùng"]},"actions":["Cho thuốc chẹn alpha (tamsulosin) hỗ trợ tống sỏi, hẹn tái khám","Giảm đau bằng NSAID đường tiêm hoặc đặt hậu môn, theo dõi đáp ứng","Loại trừ nhiễm trùng niệu kèm tắc nghẽn: nhiệt độ, tổng phân tích nước tiểu, công thức máu, CRP","Cho tiêm opioid liều cao kéo dài rồi cho về không đánh giá","Hướng dẫn lọc nước tiểu, uống đủ nước, quay lại ngay khi sốt hoặc đau không giảm","Làm hình ảnh xác định sỏi: siêu âm và CT liều thấp"]}}'::jsonb,
  '456b5768804747734dc3e942e2429763e179e5ee7cbacdcb389e5b8749e09e0d'
)
on conflict (case_id) do update set
