values (
  'ngoai-tiet-nieu-001',
  '{"schema_version":"1.0.0","case_id":"ngoai-tiet-nieu-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-eau-urolithiasis-7478a8988584","resource_type":"guideline","source":"https://uroweb.org/guidelines/urolithiasis","title":"EAU Guidelines on Urolithiasis, 2024.","organization":null,"year_version":null,"citation":"EAU Guidelines on Urolithiasis, 2024.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-tiet-nieu-001-2","resource_type":"textbook","source":"Giáo trình Ngoại khoa, bài Sỏi tiết niệu, Đại học Y Dược TP.HCM.","title":"Giáo trình Ngoại khoa, bài Sỏi tiết niệu, Đại học Y Dược TP.HCM.","organization":null,"year_version":null,"citation":"Giáo trình Ngoại khoa, bài Sỏi tiết niệu, Đại học Y Dược TP.HCM.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-tiet-nieu-001-3","resource_type":"textbook","source":"Bệnh học Ngoại khoa Tiết niệu, Đại học Y Hà Nội.","title":"Bệnh học Ngoại khoa Tiết niệu, Đại học Y Hà Nội.","organization":null,"year_version":null,"citation":"Bệnh học Ngoại khoa Tiết niệu, Đại học Y Hà Nội.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5],"examination_essential_indices":[1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm ruột thừa cấp","credit":"none"},{"text":"Cơn đau quặn thận phải do sỏi niệu quản 1/3 dưới, ứ nước độ 1, chưa nhiễm trùng","credit":"full"},{"text":"Xoắn tinh hoàn phải","credit":"none"},{"text":"Viêm đài bể thận cấp có nhiễm khuẩn huyết","credit":"none"}]},"action_options":[{"text":"Giảm đau bằng NSAID đường tiêm hoặc đặt hậu môn, theo dõi đáp ứng","time_minutes":3,"grade":"critical","rationale":"NSAID là lựa chọn đầu tay để giảm cơn đau quặn thận ở người không có chống chỉ định."},{"text":"Loại trừ nhiễm trùng niệu kèm tắc nghẽn: nhiệt độ, tổng phân tích nước tiểu, công thức máu, CRP","time_minutes":3,"grade":"critical","rationale":"Sỏi gây tắc kèm nhiễm trùng là cấp cứu ngoại khoa cần dẫn lưu khẩn."},{"text":"Làm hình ảnh xác định sỏi: siêu âm và CT liều thấp","time_minutes":5,"grade":"critical","rationale":"Xác định kích thước, vị trí, mật độ sỏi để chọn hướng điều trị."},{"text":"Cho thuốc chẹn alpha (tamsulosin) hỗ trợ tống sỏi, hẹn tái khám","time_minutes":3,"grade":"critical","rationale":"Điều trị tống sỏi có hỗ trợ cho sỏi niệu quản đoạn xa ≤ 10 mm chưa biến chứng, cần giải thích rõ lợi ích hạn chế."},{"text":"Hướng dẫn lọc nước tiểu, uống đủ nước, quay lại ngay khi sốt hoặc đau không giảm","time_minutes":2,"grade":"recommended","rationale":"Dặn dò dấu hiệu cảnh báo giúp phát hiện sớm biến chứng."},{"text":"Cho tiêm opioid liều cao kéo dài rồi cho về không đánh giá","time_minutes":0,"grade":"harmful","rationale":"Bỏ sót nhiễm trùng, tắc nghẽn nặng và thiếu theo dõi."}],"teaching_explanation":"Cơn đau quặn thận cần phân biệt sớm với cấp cứu ngoại khoa khác và phát hiện nhiễm trùng kèm tắc nghẽn. Sỏi nhỏ đoạn xa ít biến chứng có thể điều trị nội có theo dõi."}'::jsonb,
  'e9a9cd524f7a334ac9ec72c83180e252aad326310da617feb65ec7a621ee5b6e'
)
