insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-tiet-nieu-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-tiet-nieu-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Bí tiểu cấp ở người lớn tuổi tiểu khó nhiều năm","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":72,"sex":"nam","patient_label":"Ông L.V.B."},"presentation":{"intro":"Người bệnh đến cấp cứu vì không tiểu được 12 giờ, đau tức vùng hạ vị.","place":null,"clock":null,"night":false},"vitals":{"hr":94,"sbp":158,"dbp":96,"rr":20,"temperature_c":36.8,"spo2":98},"history":[{"question":"Không tiểu được từ khi nào, có uống rượu hoặc dùng thuốc gì trước đó không?","response":"Không tiểu được 12 giờ, tối qua uống rượu và uống thuốc cảm có chlorpheniramin."},{"question":"Trước đây có tiểu khó, tiểu đêm, tia tiểu yếu không?","response":"Hơn ba năm nay tiểu đêm 3 đến 4 lần, tia yếu, tiểu ngắt quãng, chưa đi khám."},{"question":"Có tiểu máu, sốt, tiểu buốt không?","response":"Không tiểu máu, không sốt, không tiểu buốt."},{"question":"Có chấn thương, thủ thuật niệu đạo trước đây không?","response":"Không."},{"question":"Có đái tháo đường, bệnh thần kinh, táo bón nhiều ngày không?","response":"Không đái tháo đường; táo bón nhẹ 2 ngày nay."},{"question":"Đang dùng thuốc gì thường xuyên?","response":"Thuốc huyết áp amlodipin; thỉnh thoảng thuốc cảm."},{"question":"Tiền sử gia đình ung thư tuyến tiền liệt?","response":"Không rõ."}],"examination":[{"group":"K","item":"Khám bụng","finding":"Cầu bàng quang căng đến sát rốn, gõ đục, ấn đau."},{"group":"K","item":"Thăm trực tràng","finding":"Tuyến tiền liệt to đối xứng, mật độ chắc đàn hồi, mất rãnh giữa, không nhân cứng, không đau."},{"group":"K","item":"Khám bộ phận sinh dục ngoài","finding":"Không hẹp lỗ sáo, không chảy dịch."},{"group":"K","item":"Thần kinh vùng chậu","finding":"Cảm giác tầng sinh môn và trương lực cơ thắt hậu môn bình thường."},{"group":"K","item":"Sinh hiệu","finding":"Huyết áp 158/96 mmHg, mạch 94, đau tức làm bồn chồn."}],"investigations":[{"name":"Siêu âm bụng và tuyến tiền liệt","duration_minutes":15,"result":"Bàng quang căng 1100 mL; tuyến tiền liệt 62 mL, thùy giữa lồi vào bàng quang; thận hai bên ứ nước độ 1."},{"name":"Creatinin, ure, điện giải","duration_minutes":10,"result":"Creatinin 138 µmol/L, ure 9,4 mmol/L, Na 138, K 4,6 mmol/L."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Bạch cầu (-), hồng cầu (+), nitrit âm."},{"name":"PSA toàn phần","duration_minutes":10,"result":"6,9 ng/mL; đang bí tiểu, sẽ làm lại sau khi ổn định."},{"name":"Chụp cộng hưởng từ vùng chậu ngay trong đêm cấp cứu","duration_minutes":10,"result":"Không cần thiết lúc bí tiểu cấp, không thay đổi xử trí ban đầu."}],"choices":{"diagnosis":{"ydx":["Bí tiểu do hẹp niệu đạo","Bí tiểu do bàng quang thần kinh","Sỏi niệu đạo","Bí tiểu cấp do phì đại lành tính tuyến tiền liệt, suy thận sau thận mức nhẹ do tắc nghẽn"]},"actions":["Ngừng thuốc kháng cholinergic và thuốc cảm có chlorpheniramin","Hẹn thử rút thông, siêu âm thể tích tồn lưu, hội chẩn Ngoại tiết niệu","Bắt đầu thuốc chẹn alpha trước khi rút thông","Đặt thông tiểu Foley giải áp bàng quang, ghi nhận thể tích nước tiểu","Theo dõi lượng nước tiểu và điện giải sau giải áp, nguy cơ đa niệu sau tắc nghẽn và tiểu máu","Đặt thông cứng nhiều lần cố mở đường khi đau, không dùng bôi trơn"]}}'::jsonb,
  'c874d48cbbb925fd302961a92b4880211f4101da4aeb7733b3b2328b5ec48c97'
)
on conflict (case_id) do update set
