values (
  'ngoai-tiet-nieu-002',
  '{"schema_version":"1.0.0","case_id":"ngoai-tiet-nieu-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-tiet-nieu-002-1","resource_type":"other","source":"EAU Guidelines on Non-neurogenic Male LUTS, 2024.","title":"EAU Guidelines on Non-neurogenic Male LUTS, 2024.","organization":null,"year_version":null,"citation":"EAU Guidelines on Non-neurogenic Male LUTS, 2024.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-tiet-nieu-002-2","resource_type":"textbook","source":"Giáo trình Ngoại khoa, bài U xơ tuyến tiền liệt, Đại học Y Hà Nội.","title":"Giáo trình Ngoại khoa, bài U xơ tuyến tiền liệt, Đại học Y Hà Nội.","organization":null,"year_version":null,"citation":"Giáo trình Ngoại khoa, bài U xơ tuyến tiền liệt, Đại học Y Hà Nội.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-tiet-nieu-002-3","resource_type":"other","source":"AUA Guideline: Management of Benign Prostatic Hyperplasia, 2023.","title":"AUA Guideline: Management of Benign Prostatic Hyperplasia, 2023.","organization":null,"year_version":null,"citation":"AUA Guideline: Management of Benign Prostatic Hyperplasia, 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,4,5],"examination_essential_indices":[0,1,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Bí tiểu do hẹp niệu đạo","credit":"none"},{"text":"Bí tiểu do bàng quang thần kinh","credit":"none"},{"text":"Bí tiểu cấp do phì đại lành tính tuyến tiền liệt, suy thận sau thận mức nhẹ do tắc nghẽn","credit":"full"},{"text":"Sỏi niệu đạo","credit":"none"}]},"action_options":[{"text":"Đặt thông tiểu Foley giải áp bàng quang, ghi nhận thể tích nước tiểu","time_minutes":3,"grade":"critical","rationale":"Bí tiểu cấp cần giải áp ngay để giảm đau và bảo vệ thận."},{"text":"Theo dõi lượng nước tiểu và điện giải sau giải áp, nguy cơ đa niệu sau tắc nghẽn và tiểu máu","time_minutes":3,"grade":"critical","rationale":"Giải áp có thể gây tiểu nhiều và mất nước, tiểu máu do giảm áp."},{"text":"Bắt đầu thuốc chẹn alpha trước khi rút thông","time_minutes":3,"grade":"critical","rationale":"Tăng tỷ lệ rút thông thành công."},{"text":"Ngừng thuốc kháng cholinergic và thuốc cảm có chlorpheniramin","time_minutes":2,"grade":"critical","rationale":"Thuốc là yếu tố khởi phát bí tiểu."},{"text":"Hẹn thử rút thông, siêu âm thể tích tồn lưu, hội chẩn Ngoại tiết niệu","time_minutes":3,"grade":"recommended","rationale":"Đánh giá khả năng tự tiểu, lên kế hoạch phẫu thuật nếu thất bại."},{"text":"Đặt thông cứng nhiều lần cố mở đường khi đau, không dùng bôi trơn","time_minutes":0,"grade":"harmful","rationale":"Gây tổn thương niệu đạo, chảy máu và hẹp niệu đạo."}],"teaching_explanation":"Bí tiểu cấp ở nam lớn tuổi thường do phì đại lành tính tuyến tiền liệt có yếu tố thúc đẩy. Giải áp đúng, theo dõi sau giải áp và hoạch định điều trị lâu dài."}'::jsonb,
  '270c8cc0c6df2f5b806853f66269a9d87f855568323fbdc4e320b08d6ef137ce'
)
