insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-tiet-nieu-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-tiet-nieu-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau bìu trái đột ngột ở thiếu niên","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":15,"sex":"nam","patient_label":"Em N.M.K."},"presentation":{"intro":"Em đến cấp cứu cùng mẹ vì đau bìu trái dữ dội 4 giờ, buồn nôn.","place":null,"clock":null,"night":false},"vitals":{"hr":110,"sbp":128,"dbp":76,"rr":22,"temperature_c":37,"spo2":99},"history":[{"question":"Đau bắt đầu lúc nào, đột ngột hay từ từ?","response":"Đau dữ dội đột ngột lúc 2 giờ sáng, đánh thức em dậy, 4 giờ nay."},{"question":"Có buồn nôn, nôn không?","response":"Buồn nôn và nôn hai lần."},{"question":"Có sốt, tiểu buốt, chảy dịch niệu đạo không?","response":"Không sốt, không tiểu buốt, không chảy dịch."},{"question":"Có chấn thương bìu hoặc vận động mạnh trước đó không?","response":"Không chấn thương rõ; trước khi ngủ đá bóng cả buổi chiều."},{"question":"Trước đây có những cơn đau bìu tự hết không?","response":"Có hai lần đau bìu thoáng qua tuần trước, tự hết."},{"question":"Có quan hệ tình dục không?","response":"Không."},{"question":"Có tiền sử gia đình bị xoắn tinh hoàn không?","response":"Không biết."}],"examination":[{"group":"K","item":"Quan sát bìu","finding":"Bìu trái sưng đỏ nhẹ, tinh hoàn trái nằm cao và ngang."},{"group":"K","item":"Sờ tinh hoàn","finding":"Tinh hoàn trái căng, đau nhiều, mào tinh khó phân biệt, thừng tinh ngắn, dày."},{"group":"K","item":"Phản xạ cơ bìu (cremaster)","finding":"Mất bên trái, còn bên phải."},{"group":"K","item":"Dấu Prehn","finding":"Nâng tinh hoàn lên không giảm đau, đau tăng thêm."},{"group":"K","item":"Khám bụng, thận","finding":"Bụng mềm, không đau; không rung thận."}],"investigations":[{"name":"Siêu âm Doppler bìu khẩn","duration_minutes":15,"result":"Tinh hoàn trái kích thước lớn hơn, không thấy tín hiệu tưới máu; thừng tinh có hình xoáy; bên phải bình thường."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Bình thường, không bạch cầu."},{"name":"Công thức máu, CRP","duration_minutes":10,"result":"Bạch cầu 10,8 G/L, CRP 4 mg/L."},{"name":"Điểm TWIST (sưng, đau cứng, nôn, tinh hoàn cao, mất cremaster)","duration_minutes":10,"result":"Điểm 7, nguy cơ cao."},{"name":"Chờ kết quả nuôi cấy nước tiểu 48 giờ và điều trị kháng sinh thử trước khi quyết định","duration_minutes":10,"result":"Làm chậm thời gian cứu tinh hoàn, không có chỉ định."}],"choices":{"diagnosis":{"ydx":["Xoắn thừng tinh trái, nghi ngờ cao, cần phẫu thuật thám sát cấp cứu","Viêm mào tinh hoàn cấp","Thoát vị bẹn nghẹt","Xoắn phần phụ tinh hoàn"]},"actions":["Giảm đau đường tĩnh mạch, giải thích cho người nhà và xin đồng ý phẫu thuật","Nghi ngờ xoắn tinh hoàn, báo ngay bác sĩ Ngoại niệu để thám sát khẩn","Chẩn đoán viêm mào tinh hoàn, cho kháng sinh và về nhà","Sau mổ: cố định cả hai tinh hoàn, theo dõi sưng, nhiễm trùng, tư vấn khả năng teo tinh hoàn","Nhịn ăn, chuẩn bị gây mê và chuyển phòng mổ","Có thể nắn xoắn ngoài bằng tay mở sách trong lúc chờ nếu thành thạo, vẫn phải mổ"]}}'::jsonb,
  'b3059c125f2b983cf594494562e9245d2f442dbe2635dc5b0ef2778452989a24'
)
on conflict (case_id) do update set
