values (
  'ngoai-vu-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-vu-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sờ thấy khối ở vú trái sau tắm","setting":"giuong","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":52,"sex":"nữ","patient_label":"Bà P.T.N."},"presentation":{"intro":"Bà đến phòng khám ngoại vì tự sờ thấy khối ở vú trái 6 tuần, không đau.","place":null,"clock":null,"night":false},"vitals":{"hr":78,"sbp":126,"dbp":78,"rr":16,"temperature_c":36.7,"spo2":99},"history":[{"question":"Khối xuất hiện từ khi nào, có to lên không?","response":"Phát hiện cách đây 6 tuần khi tắm, có vẻ to hơn một chút."},{"question":"Có đau, tiết dịch núm vú, thay đổi da vú không?","response":"Không đau, không tiết dịch, da vú không đổi màu."},{"question":"Tiền sử kinh nguyệt, sinh con, cho con bú?","response":"Có kinh lần đầu 12 tuổi, mãn kinh 49 tuổi, sinh 2 con, cho con bú mỗi bé 12 tháng."},{"question":"Tiền sử gia đình ung thư vú, buồng trứng?","response":"Chị gái ung thư vú lúc 58 tuổi; mẹ không bệnh."},{"question":"Có dùng liệu pháp hormone thay thế hoặc xạ trị vùng ngực không?","response":"Không."},{"question":"Có sụt cân, đau xương, ho kéo dài, đau đầu không?","response":"Không có dấu hiệu toàn thân."},{"question":"Đã chụp nhũ ảnh định kỳ chưa?","response":"Lần cuối cách đây 3 năm, bình thường."}],"examination":[{"group":"K","item":"Quan sát và sờ vú trái","finding":"Khối 1,8 cm ở góc trên ngoài, cứng, bờ không đều, ít di động, không dính da, không co kéo núm vú."},{"group":"K","item":"Vú phải","finding":"Không sờ thấy khối."},{"group":"K","item":"Hạch nách, thượng đòn hai bên","finding":"Hạch nách trái không sờ thấy; hạch thượng đòn không."},{"group":"K","item":"Khám bụng, gan","finding":"Gan không to; không đau xương cột sống khi gõ."},{"group":"K","item":"Tình trạng chung","finding":"ECOG 0."}],"investigations":[{"name":"Nhũ ảnh hai vú","duration_minutes":10,"result":"Khối mật độ cao, bờ tua gai ở góc trên ngoài vú trái, kèm vi vôi hóa; BI-RADS 5."},{"name":"Siêu âm vú và hạch nách","duration_minutes":15,"result":"Khối giảm âm 1,8 cm, trục dọc, bờ góc cạnh; hạch nách trái hình thái bình thường; BI-RADS 5."},{"name":"Sinh thiết lõi dưới hướng dẫn siêu âm với hóa mô miễn dịch","duration_minutes":15,"result":"Ung thư biểu mô ống xâm lấn độ 2; ER dương 95%, PR dương 70%, HER2 âm (điểm 1+), Ki-67 18%."},{"name":"Công thức máu, chức năng gan thận, canxi, phosphatase kiềm","duration_minutes":10,"result":"Trong giới hạn bình thường."},{"name":"PET-CT toàn thân thường quy cho mọi ung thư vú giai đoạn I","duration_minutes":40,"result":"Không có chỉ định ở giai đoạn sớm không triệu chứng, hạch lâm sàng âm."}],"choices":{"diagnosis":{"ydx":["Viêm vú mạn","Ung thư biểu mô ống xâm lấn vú trái, cT1c N0 M0, ER dương, HER2 âm","Bệnh xơ nang tuyến vú","U xơ tuyến vú"]},"actions":["Cắt bỏ khối đơn thuần không sinh thiết trước rồi chờ giải phẫu bệnh","Hội chẩn đa chuyên khoa ung bướu vú","Sinh thiết lõi trước điều trị với đầy đủ ER, PR, HER2, Ki-67","Tư vấn di truyền do gia đình có chị gái ung thư vú","Sau mổ: xạ trị toàn vú, điều trị nội tiết (thuốc ức chế aromatase sau mãn kinh)","Phẫu thuật bảo tồn vú kèm sinh thiết hạch cửa, giải thích khả năng mổ lại nếu rìa dương tính"]}}'::jsonb,
  'fdc1e44f3d7c84ca2579b5b7c36dcd3edbda853180fbad1a927846359b1dcf23'
)
