  '{"schema_version":"1.0.0","case_id":"ngoai-vu-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-vu-001-1","resource_type":"other","source":"NCCN Clinical Practice Guidelines in Oncology: Breast Cancer, 2025.","title":"NCCN Clinical Practice Guidelines in Oncology: Breast Cancer, 2025.","organization":null,"year_version":null,"citation":"NCCN Clinical Practice Guidelines in Oncology: Breast Cancer, 2025.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-breast-esmo-2024","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/38101773/","title":"ESMO Clinical Practice Guideline: Early Breast Cancer, 2024.","organization":null,"year_version":null,"citation":"ESMO Clinical Practice Guideline: Early Breast Cancer, 2024.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-vu-001-3","resource_type":"other","source":"AJCC Cancer Staging Manual, 8th edition, 2017.","title":"AJCC Cancer Staging Manual, 8th edition, 2017.","organization":null,"year_version":null,"citation":"AJCC Cancer Staging Manual, 8th edition, 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-vu-001-4","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị ung thư vú, Bộ Y tế Việt Nam.","title":"Hướng dẫn chẩn đoán và điều trị ung thư vú, Bộ Y tế Việt Nam.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị ung thư vú, Bộ Y tế Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"U xơ tuyến vú","credit":"none"},{"text":"Bệnh xơ nang tuyến vú","credit":"none"},{"text":"Viêm vú mạn","credit":"none"},{"text":"Ung thư biểu mô ống xâm lấn vú trái, cT1c N0 M0, ER dương, HER2 âm","credit":"full"}]},"action_options":[{"text":"Sinh thiết lõi trước điều trị với đầy đủ ER, PR, HER2, Ki-67","time_minutes":3,"grade":"critical","rationale":"Xác định mô bệnh học và dấu ấn sinh học quyết định điều trị."},{"text":"Hội chẩn đa chuyên khoa ung bướu vú","time_minutes":3,"grade":"recommended","rationale":"Xác định giai đoạn lâm sàng cT1c N0 và kế hoạch điều trị."},{"text":"Phẫu thuật bảo tồn vú kèm sinh thiết hạch cửa, giải thích khả năng mổ lại nếu rìa dương tính","time_minutes":5,"grade":"recommended","rationale":"Với khối 1,8 cm, tỷ lệ khối/vú phù hợp, bảo tồn cho kết quả sống còn tương đương cắt vú."},{"text":"Sau mổ: xạ trị toàn vú, điều trị nội tiết (thuốc ức chế aromatase sau mãn kinh)","time_minutes":3,"grade":"recommended","rationale":"Giảm tái phát tại chỗ và xa."},{"text":"Tư vấn di truyền do gia đình có chị gái ung thư vú","time_minutes":2,"grade":"recommended","rationale":"Cân nhắc xét nghiệm BRCA theo tiêu chí."},{"text":"Cắt bỏ khối đơn thuần không sinh thiết trước rồi chờ giải phẫu bệnh","time_minutes":0,"grade":"harmful","rationale":"Phẫu thuật không kế hoạch làm khó điều trị đúng giai đoạn."}],"teaching_explanation":"Khối vú cứng, bờ không đều, BI-RADS 5 cần sinh thiết lõi trước điều trị; thể ER dương, HER2 âm, hạch lâm sàng âm điều trị chủ yếu bằng phẫu thuật bảo tồn, xạ trị và nội tiết."}'::jsonb,
