insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-noi-tiet-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-noi-tiet-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nhân giáp phát hiện qua siêu âm kiểm tra sức khỏe","setting":"giuong","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":44,"sex":"nữ","patient_label":"Bà H.T.M."},"presentation":{"intro":"Bà đến phòng khám ngoại vì phát hiện nhân giáp phải khi siêu âm kiểm tra sức khỏe định kỳ.","place":null,"clock":null,"night":false},"vitals":{"hr":76,"sbp":118,"dbp":74,"rr":16,"temperature_c":36.6,"spo2":99},"history":[{"question":"Có tự sờ thấy khối ở cổ hoặc thấy cổ to không?","response":"Mới sờ thấy cục nhỏ ở cổ phải sau khi có kết quả siêu âm."},{"question":"Có khàn tiếng, khó nuốt, khó thở không?","response":"Không khàn tiếng, không khó nuốt, không khó thở."},{"question":"Có sụt cân, run tay, hồi hộp, sợ nóng hoặc mệt, tăng cân, sợ lạnh không?","response":"Không có triệu chứng cường hay suy giáp."},{"question":"Tiền sử chiếu xạ vùng đầu cổ khi nhỏ?","response":"Không."},{"question":"Tiền sử gia đình ung thư giáp hoặc bệnh nội tiết?","response":"Không."},{"question":"Sống ở vùng thiếu iod, bệnh giáp trước đây?","response":"Sống ở thành phố, chưa bệnh giáp."},{"question":"Thuốc đang dùng?","response":"Không dùng thuốc thường xuyên."}],"examination":[{"group":"K","item":"Sờ tuyến giáp","finding":"Nhân thùy phải khoảng 1,5 cm, cứng, di động theo nuốt, không đau, bờ không rõ."},{"group":"K","item":"Thùy trái và eo","finding":"Không sờ thấy nhân."},{"group":"K","item":"Hạch cổ","finding":"Không sờ thấy hạch cổ hai bên."},{"group":"K","item":"Giọng nói","finding":"Giọng bình thường."},{"group":"K","item":"Dấu hiệu cường giáp, suy giáp","finding":"Không run tay, mạch 76, da bình thường."}],"investigations":[{"name":"Siêu âm tuyến giáp và hạch cổ","duration_minutes":15,"result":"Nhân thùy phải 1,6 cm giảm âm, bờ không đều, có vi vôi hóa, cao hơn rộng; phân loại ACR TI-RADS TR5 (EU-TIRADS 5); không hạch cổ nghi ngờ."},{"name":"TSH, FT4","duration_minutes":10,"result":"TSH 1,2 mIU/L, FT4 bình thường."},{"name":"Chọc hút tế bào bằng kim nhỏ dưới siêu âm","duration_minutes":15,"result":"Bethesda VI: ung thư biểu mô nhú."},{"name":"Calci máu, PTH trước mổ","duration_minutes":10,"result":"Calci 2,3 mmol/L, PTH bình thường (giá trị nền)."},{"name":"Xạ hình iod phóng xạ cho mọi nhân giáp có TSH bình thường","duration_minutes":10,"result":"Không có chỉ định; nhân nhìn nguội không phân biệt lành ác và TSH bình thường."}],"choices":{"diagnosis":{"ydx":["Ung thư biểu mô nhú tuyến giáp thùy phải, cT1b N0 M0, chưa xâm lấn ngoài tuyến","Viêm giáp Hashimoto","Ung thư biểu mô tuyến giáp thể tủy","Bướu giáp nhân lành tính độc lập"]},"actions":["Sau mổ: theo dõi calci, khàn tiếng, tụ máu cổ, giải phẫu bệnh sau mổ, levothyroxine","Xác định tế bào học bằng chọc hút kim nhỏ dưới siêu âm","Mổ cắt bỏ nhân đơn thuần không có kết quả tế bào học trước mổ","Theo dõi dài hạn: thyroglobulin, siêu âm cổ định kỳ","Hội chẩn phẫu thuật: cắt thùy giáp hoặc cắt giáp toàn bộ theo nguy cơ","Đánh giá hạch cổ và chức năng dây thanh trước mổ (siêu âm, nội soi thanh quản)"]}}'::jsonb,
  '3d38a13e2303ae1788cc5924964e389dc29ce25780e05328e84949cc661fbc31'
)
