values (
  'ngoai-noi-tiet-001',
  '{"schema_version":"1.0.0","case_id":"ngoai-noi-tiet-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-thyroid-nodule-ata-2015","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/26462967/","title":"2015 American Thyroid Association Management Guidelines for Adult Patients with Thyroid Nodules and Differentiated Thyroid Cancer.","organization":null,"year_version":null,"citation":"2015 American Thyroid Association Management Guidelines for Adult Patients with Thyroid Nodules and Differentiated Thyroid Cancer.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-tirads-acr-2017","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/28372962/","title":"ACR TI-RADS, American College of Radiology, 2017.","organization":null,"year_version":null,"citation":"ACR TI-RADS, American College of Radiology, 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-bethesda-2023","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/37427847/","title":"The Bethesda System for Reporting Thyroid Cytopathology, 2023.","organization":null,"year_version":null,"citation":"The Bethesda System for Reporting Thyroid Cytopathology, 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-noi-tiet-001-4","resource_type":"textbook","source":"Giáo trình Ngoại khoa, bài Bệnh lý tuyến giáp, Đại học Y Hà Nội.","title":"Giáo trình Ngoại khoa, bài Bệnh lý tuyến giáp, Đại học Y Hà Nội.","organization":null,"year_version":null,"citation":"Giáo trình Ngoại khoa, bài Bệnh lý tuyến giáp, Đại học Y Hà Nội.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Bướu giáp nhân lành tính độc lập","credit":"none"},{"text":"Viêm giáp Hashimoto","credit":"none"},{"text":"Ung thư biểu mô nhú tuyến giáp thùy phải, cT1b N0 M0, chưa xâm lấn ngoài tuyến","credit":"full"},{"text":"Ung thư biểu mô tuyến giáp thể tủy","credit":"none"}]},"action_options":[{"text":"Xác định tế bào học bằng chọc hút kim nhỏ dưới siêu âm","time_minutes":3,"grade":"critical","rationale":"Nhân TR5 trên 1 cm có chỉ định chọc hút để quyết định phẫu thuật."},{"text":"Đánh giá hạch cổ và chức năng dây thanh trước mổ (siêu âm, nội soi thanh quản)","time_minutes":3,"grade":"recommended","rationale":"Phát hiện hạch, liệt dây thanh trước mổ và làm cơ sở so sánh."},{"text":"Hội chẩn phẫu thuật: cắt thùy giáp hoặc cắt giáp toàn bộ theo nguy cơ","time_minutes":5,"grade":"recommended","rationale":"Ung thư nhú 1 đến 4 cm không xâm lấn, cN0: cắt thùy là đủ hoặc cắt toàn bộ nếu có yếu tố nguy cơ hoặc bệnh nhân chọn."},{"text":"Sau mổ: theo dõi calci, khàn tiếng, tụ máu cổ, giải phẫu bệnh sau mổ, levothyroxine","time_minutes":3,"grade":"recommended","rationale":"Đề phòng biến chứng hạ calci, tổn thương dây thanh quặt ngược."},{"text":"Theo dõi dài hạn: thyroglobulin, siêu âm cổ định kỳ","time_minutes":3,"grade":"recommended","rationale":"Phát hiện tái phát."},{"text":"Mổ cắt bỏ nhân đơn thuần không có kết quả tế bào học trước mổ","time_minutes":0,"grade":"harmful","rationale":"Mổ không chuẩn bị không đúng mức cắt và có thể phải mổ lại."}],"teaching_explanation":"Nhân giáp có dấu hiệu nghi ngờ trên siêu âm cần chọc hút kim nhỏ; ung thư nhú nhỏ không xâm lấn tiên lượng tốt, điều trị chính là phẫu thuật."}'::jsonb,
