insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-mach-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-mach-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau chân trái đột ngột, lạnh, tê bì ở người rung nhĩ","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":68,"sex":"nam","patient_label":"Ông Đ.V.C."},"presentation":{"intro":"Người bệnh đến cấp cứu vì đau chân trái đột ngột 5 giờ, chân lạnh và tê.","place":null,"clock":null,"night":false},"vitals":{"hr":112,"sbp":156,"dbp":92,"rr":20,"temperature_c":36.8,"spo2":96},"history":[{"question":"Đau chân bắt đầu thế nào, từ lúc nào?","response":"Đau đột ngột bắp chân trái lúc 9 giờ sáng, đã 5 giờ, đau dữ dội."},{"question":"Chân có lạnh, tê, yếu hay thay đổi màu không?","response":"Bàn chân lạnh, tái nhợt, tê bì cả bàn chân và khó gập ngón chân."},{"question":"Trước đây có đau cách hồi khi đi bộ không?","response":"Không."},{"question":"Có bệnh tim, rung nhĩ hoặc dùng thuốc chống đông không?","response":"Biết rung nhĩ hai năm, không dùng chống đông vì cho là không cần."},{"question":"Có hút thuốc, tăng huyết áp, đái tháo đường, rối loạn mỡ máu không?","response":"Hút thuốc 20 năm, tăng huyết áp; không đái tháo đường."},{"question":"Có chấn thương hoặc thủ thuật mạch máu gần đây không?","response":"Không."},{"question":"Có dị ứng thuốc cản quang hoặc bệnh thận không?","response":"Không dị ứng; chưa biết bệnh thận."}],"examination":[{"group":"K","item":"Nhìn và sờ chân trái","finding":"Bàn chân nhợt, lạnh từ dưới gối, mao mạch làm đầy chậm."},{"group":"K","item":"Mạch","finding":"Mạch bẹn trái yếu; khoeo, chày sau, mu chân trái không bắt được; chân phải mạch đầy đủ."},{"group":"K","item":"Cảm giác và vận động","finding":"Mất cảm giác nhẹ vượt quá ngón chân; gập bàn chân yếu (3/5) nhưng còn."},{"group":"K","item":"Tim","finding":"Rối loạn nhịp hoàn toàn không đều, tần số 112 lần/phút."},{"group":"K","item":"Khoang cơ bắp chân","finding":"Mềm, chưa căng, đau khi căng thụ động nhẹ."}],"investigations":[{"name":"Doppler cầm tay đo áp lực cổ chân","duration_minutes":10,"result":"Chân trái không nghe tín hiệu động mạch chày, còn tín hiệu tĩnh mạch; chân phải bình thường."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Rung nhĩ đáp ứng thất nhanh 112 lần/phút."},{"name":"Xét nghiệm đông máu, công thức máu, creatinin, điện giải, CK, lactate","duration_minutes":10,"result":"INR 1,0; Hb 142 g/L; creatinin 98 µmol/L; K 4,3; CK 180 U/L; lactate 2,2 mmol/L."},{"name":"Chụp CT mạch máu chi dưới","duration_minutes":40,"result":"Tắc đột ngột động mạch khoeo trái đoạn thấp, hình ảnh huyết khối tắc, mạch dưới gối nghèo; không có mảng vữa nặng."},{"name":"Chờ kết quả siêu âm tim 24 giờ rồi mới bắt đầu điều trị","duration_minutes":15,"result":"Chậm tái tưới máu, không phù hợp với cấp cứu mạch tạng."}],"choices":{"diagnosis":{"ydx":["Hội chứng khoang cấp đơn thuần","Huyết khối tĩnh mạch sâu chi dưới","Bệnh động mạch ngoại biên mạn tính đợt kịch phát","Thiếu máu chi dưới cấp do tắc động mạch do huyết khối từ tim (rung nhĩ), Rutherford IIb"]},"actions":["Chụp CT mạch hoặc chụp mạch trong mổ để định vị","Hội chẩn khẩn phẫu thuật mạch máu, chuẩn bị mổ lấy huyết khối","Sau mổ: theo dõi hội chứng khoang, tiêu cơ vân, tăng kali, tổn thương thận cấp, chống đông kéo dài và điều trị rung nhĩ","Xoa bóp mạnh và chườm nóng chân trái chờ tự hết","Giảm đau mạnh, giữ ấm chân, nằm đầu thấp hơn chân (không nâng chân)","Heparin không phân đoạn tĩnh mạch liều tải ngay khi nghi ngờ, không chờ hình ảnh"]}}'::jsonb,
  '20fee85c456f6ab1558db61e465bbc22dcd2a4f7f6f6f76f30eb2fe2f33425da'
)
