values (
  'ngoai-mach-001',
  '{"schema_version":"1.0.0","case_id":"ngoai-mach-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-limb-esvs-2020","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31899099/","title":"Björck M và cs. Editor''s Choice: European Society for Vascular Surgery 2020 Clinical Practice Guidelines on the Management of Acute Limb Ischaemia. Eur J Vasc Endovasc Surg, 2020.","organization":null,"year_version":null,"citation":"Björck M và cs. Editor''s Choice: European Society for Vascular Surgery 2020 Clinical Practice Guidelines on the Management of Acute Limb Ischaemia. Eur J Vasc Endovasc Surg, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-pad-accaha-2024","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/38743805/","title":"2024 ACC/AHA Guideline for the Management of Lower Extremity Peripheral Artery Disease.","organization":null,"year_version":null,"citation":"2024 ACC/AHA Guideline for the Management of Lower Extremity Peripheral Artery Disease.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-mach-001-3","resource_type":"textbook","source":"Giáo trình Ngoại khoa, bài Thiếu máu chi cấp, Đại học Y Dược TP.HCM.","title":"Giáo trình Ngoại khoa, bài Thiếu máu chi cấp, Đại học Y Dược TP.HCM.","organization":null,"year_version":null,"citation":"Giáo trình Ngoại khoa, bài Thiếu máu chi cấp, Đại học Y Dược TP.HCM.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,6],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Bệnh động mạch ngoại biên mạn tính đợt kịch phát","credit":"none"},{"text":"Thiếu máu chi dưới cấp do tắc động mạch do huyết khối từ tim (rung nhĩ), Rutherford IIb","credit":"full"},{"text":"Huyết khối tĩnh mạch sâu chi dưới","credit":"none"},{"text":"Hội chứng khoang cấp đơn thuần","credit":"none"}]},"action_options":[{"text":"Heparin không phân đoạn tĩnh mạch liều tải ngay khi nghi ngờ, không chờ hình ảnh","time_minutes":2,"grade":"critical","rationale":"Chống đông ngăn lan rộng huyết khối."},{"text":"Hội chẩn khẩn phẫu thuật mạch máu, chuẩn bị mổ lấy huyết khối","time_minutes":3,"grade":"critical","rationale":"Rutherford IIb cần tái tưới máu khẩn; chi có nguy cơ mất nếu trễ quá vài giờ."},{"text":"Giảm đau mạnh, giữ ấm chân, nằm đầu thấp hơn chân (không nâng chân)","time_minutes":2,"grade":"critical","rationale":"Không chườm nóng; nâng chân làm giảm tưới máu."},{"text":"Chụp CT mạch hoặc chụp mạch trong mổ để định vị","time_minutes":5,"grade":"critical","rationale":"Xác định vị trí tắc, đánh giá mạch dưới gối."},{"text":"Sau mổ: theo dõi hội chứng khoang, tiêu cơ vân, tăng kali, tổn thương thận cấp, chống đông kéo dài và điều trị rung nhĩ","time_minutes":3,"grade":"recommended","rationale":"Hội chứng tái tưới máu có thể đe dọa tính mạng."},{"text":"Xoa bóp mạnh và chườm nóng chân trái chờ tự hết","time_minutes":0,"grade":"harmful","rationale":"Làm nặng tổn thương, chậm điều trị và có thể mất chi."}],"teaching_explanation":"Thiếu máu chi cấp ở người rung nhĩ là cấp cứu mạch máu: chống đông ngay và tái tưới máu khẩn; theo dõi hậu phẫu hội chứng tái tưới máu và hội chứng khoang."}'::jsonb,
