values (
  'ngoai-san-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-san-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau hạ vị phải dữ dội đột ngột kèm nôn ở phụ nữ trẻ","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":27,"sex":"nữ","patient_label":"Chị V.T.L."},"presentation":{"intro":"Chị đến cấp cứu vì đau hạ vị phải dữ dội đột ngột 6 giờ, nôn nhiều.","place":null,"clock":null,"night":false},"vitals":{"hr":104,"sbp":118,"dbp":72,"rr":22,"temperature_c":37.6,"spo2":99},"history":[{"question":"Đau bắt đầu thế nào, có liên quan động tác nào không?","response":"Đau đột ngột dữ dội hạ vị phải sau khi chạy xe, đau thành từng cơn rồi liên tục, 6 giờ nay."},{"question":"Có buồn nôn, nôn không?","response":"Nôn 3 lần, buồn nôn nhiều."},{"question":"Kinh nguyệt lần cuối, có chậm kinh không, ra huyết âm đạo không?","response":"Kinh cách đây 12 ngày, đều, không ra huyết bất thường; không chậm kinh."},{"question":"Có quan hệ tình dục, biện pháp tránh thai?","response":"Có chồng, dùng bao cao su."},{"question":"Tiền sử u nang buồng trứng hoặc phẫu thuật?","response":"Siêu âm 6 tháng trước phát hiện u nang buồng trứng phải 5 cm, hẹn tái khám chưa đi."},{"question":"Có sốt, tiểu buốt, khí hư?","response":"Không sốt, không tiểu buốt, không khí hư bất thường."},{"question":"Có bệnh khác, dị ứng thuốc?","response":"Không."}],"examination":[{"group":"K","item":"Khám bụng","finding":"Hố chậu phải ấn đau nhiều, phản ứng thành bụng nhẹ, không co cứng lan tỏa."},{"group":"K","item":"Khám âm đạo bằng mỏ vịt","finding":"Không ra huyết, cổ tử cung bình thường."},{"group":"K","item":"Thăm âm đạo kết hợp nắn bụng","finding":"Cạnh tử cung phải khối khoảng 7 cm, căng, di động hạn chế, đau chói khi chạm; tử cung bình thường."},{"group":"K","item":"Dấu hiệu phúc mạc, Blumberg","finding":"Blumberg nhẹ (+) hố chậu phải."},{"group":"K","item":"Tuần hoàn","finding":"Mạch nhanh 104; không có dấu mất máu."}],"investigations":[{"name":"Thử thai nhanh hCG nước tiểu hoặc máu","duration_minutes":10,"result":"Âm tính."},{"name":"Siêu âm đầu dò âm đạo kèm Doppler","duration_minutes":15,"result":"Khối 7 cm cạnh tử cung phải, echo hỗn hợp có đoạn tăng âm (nghĩ u quái); buồng trứng phải phù nề, nhiều nang nhỏ ở ngoại vi; ít dịch Douglas; Doppler còn tín hiệu động mạch yếu."},{"name":"Công thức máu, CRP","duration_minutes":10,"result":"Bạch cầu 13,2 G/L, Hb 125 g/L, CRP 12 mg/L."},{"name":"CA-125, AFP, hCG (dấu ấn u buồng trứng)","duration_minutes":10,"result":"CA-125 28 U/mL, AFP, hCG bình thường."},{"name":"Chờ nội soi theo dõi và điều trị giảm đau 48 giờ nếu Doppler còn tín hiệu","duration_minutes":20,"result":"Doppler còn tín hiệu không loại trừ xoắn; chờ làm tăng nguy cơ hoại tử buồng trứng."}],"choices":{"diagnosis":{"ydx":["Viêm ruột thừa cấp","Thai ngoài tử cung","Viêm phần phụ cấp","Xoắn u nang buồng trứng phải, nghi u quái trưởng thành"]},"actions":["Siêu âm đầu dò âm đạo kèm Doppler, nhưng không dựa vào Doppler để quyết định không mổ","Cắt buồng trứng phải ngay khi thấy tím đen mà không tháo xoắn","Phẫu thuật nội soi: tháo xoắn, bóc u quái bảo tồn buồng trứng, kiểm tra đối bên","Loại trừ thai ngoài tử cung bằng hCG","Nhịn ăn, đường truyền, giảm đau, xét nghiệm tiền phẫu và hội chẩn Sản phụ khoa cấp cứu","Hậu phẫu: giảm đau, kháng sinh dự phòng nếu cần, theo dõi giải phẫu bệnh, siêu âm theo dõi sau 6 đến 8 tuần"]}}'::jsonb,
  'b98bb1a3a78c3d1df729bf38f86b6049df470565c4aab251c1af812e0502868a'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-san-001',
  '{"schema_version":"1.0.0","case_id":"ngoai-san-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-adnexal-torsion-acog-783","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31348225/","title":"ACOG Committee Opinion No. 783: Adnexal Torsion in Adolescents, 2019.","organization":null,"year_version":null,"citation":"ACOG Committee Opinion No. 783: Adnexal Torsion in Adolescents, 2019.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-san-001-2","resource_type":"other","source":"RCOG Green-top Guideline No. 62: Management of Suspected Ovarian Masses in Premenopausal Women, 2011.","title":"RCOG Green-top Guideline No. 62: Management of Suspected Ovarian Masses in Premenopausal Women, 2011.","organization":null,"year_version":null,"citation":"RCOG Green-top Guideline No. 62: Management of Suspected Ovarian Masses in Premenopausal Women, 2011.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-san-001-3","resource_type":"textbook","source":"Giáo trình Sản phụ khoa, Đại học Y Hà Nội.","title":"Giáo trình Sản phụ khoa, Đại học Y Hà Nội.","organization":null,"year_version":null,"citation":"Giáo trình Sản phụ khoa, Đại học Y Hà Nội.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm ruột thừa cấp","credit":"none"},{"text":"Thai ngoài tử cung","credit":"none"},{"text":"Xoắn u nang buồng trứng phải, nghi u quái trưởng thành","credit":"full"},{"text":"Viêm phần phụ cấp","credit":"none"}]},"action_options":[{"text":"Nhịn ăn, đường truyền, giảm đau, xét nghiệm tiền phẫu và hội chẩn Sản phụ khoa cấp cứu","time_minutes":3,"grade":"critical","rationale":"Nghi xoắn phần phụ là cấp cứu vì thời gian cửa sổ cứu buồng trứng ngắn."},{"text":"Loại trừ thai ngoài tử cung bằng hCG","time_minutes":2,"grade":"critical","rationale":"Thai ngoài vỡ là chẩn đoán phân biệt cấp cứu khác cần loại trừ."},{"text":"Siêu âm đầu dò âm đạo kèm Doppler, nhưng không dựa vào Doppler để quyết định không mổ","time_minutes":5,"grade":"critical","rationale":"Doppler còn tín hiệu không loại trừ xoắn."},{"text":"Phẫu thuật nội soi: tháo xoắn, bóc u quái bảo tồn buồng trứng, kiểm tra đối bên","time_minutes":5,"grade":"critical","rationale":"Bảo tồn buồng trứng cho phụ nữ trẻ, ngay cả khi buồng trứng tím."},{"text":"Hậu phẫu: giảm đau, kháng sinh dự phòng nếu cần, theo dõi giải phẫu bệnh, siêu âm theo dõi sau 6 đến 8 tuần","time_minutes":3,"grade":"recommended","rationale":"Đánh giá phục hồi buồng trứng và u đối bên."},{"text":"Cắt buồng trứng phải ngay khi thấy tím đen mà không tháo xoắn","time_minutes":0,"grade":"harmful","rationale":"Buồng trứng thường hồi phục sau tháo xoắn dù hình thái tím."}],"teaching_explanation":"Đau hạ vị đột ngột kèm nôn ở phụ nữ trẻ có u nang buồng trứng phải nghĩ xoắn phần phụ; phẫu thuật nội soi tháo xoắn và bảo tồn buồng trứng là nguyên tắc."}'::jsonb,
  'f5f0dc6e44b37839cb57a2e2b3f0c2499714637fbd0ad9711d1c879f88683371'
)
