insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đột ngột ngã gục khi đang đi bộ, không thở, không bắt được mạch","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nam","patient_label":"Ông L. V. T."},"presentation":{"intro":"Phòng cấp cứu. Nhân viên y tế đẩy xe cấp cứu đến người đàn ông ngã gục ở sảnh bệnh viện 1 phút trước, người nhà kể ông kêu đau ngực vài giờ trước đó. Ông bất tỉnh, không đáp ứng.","place":null,"clock":null,"night":false},"vitals":{"hr":40,"sbp":40,"dbp":20,"rr":4,"temperature_c":36.5,"spo2":60},"history":[{"question":"Ông ngã gục lúc nào, có ai chứng kiến không?","response":"Ngã gục cách đây khoảng 1 phút ngay trước mắt tôi, đang nói chuyện thì đổ xuống, không kêu, không co giật."},{"question":"Trước đó ông có đau ngực, khó thở, ngất không?","response":"Sáng nay ông kêu đau thắt ngực lan tay trái gần 2 giờ, định đi khám."},{"question":"Ông có bệnh tim, tăng huyết áp, đái tháo đường không?","response":"Tăng huyết áp, đái tháo đường typ 2 nhiều năm, hút thuốc lá nhiều."},{"question":"Ông có dùng thuốc chống đông hoặc có dị ứng thuốc không?","response":"Không dùng thuốc chống đông, không dị ứng thuốc đã biết."},{"question":"Ông có chấn thương đầu hay bệnh gì khác không?","response":"Không té ngã chấn thương, không bệnh gan thận."},{"question":"Người nhà có biết ông đã dặn gì về hồi sức không?","response":"Gia đình mong muốn cứu hết mức."},{"question":"Ông từng đặt stent hay mổ tim chưa?","response":"Chưa từng."}],"examination":[{"group":"K","item":"Đáp ứng và hơi thở","finding":"Gọi lay không đáp ứng, ngừng thở hoặc thở ngáp cá, không có lồng ngực di động đều."},{"group":"K","item":"Bắt mạch cảnh (không quá 10 giây)","finding":"Không bắt được mạch cảnh và mạch bẹn."},{"group":"K","item":"Đường thở","finding":"Không có dị vật trong miệng, hàm không cứng."},{"group":"K","item":"Da và đồng tử","finding":"Da tái xanh, đồng tử 4 mm, phản xạ ánh sáng yếu."},{"group":"K","item":"Dấu chấn thương","finding":"Không vết thương, không biến dạng lồng ngực."}],"investigations":[{"name":"Gắn miếng dán máy sốc điện, đọc nhịp trên monitor","duration_minutes":10,"result":"Rung thất sóng thô, biên độ lớn."},{"name":"Đường huyết mao mạch","duration_minutes":10,"result":"Đường huyết 14,2 mmol/L."},{"name":"Khí máu động mạch, lactate, điện giải đồ (lấy khi có đường truyền)","duration_minutes":10,"result":"pH 7,05; lactate 9,5 mmol/L; K 4,6 mmol/L; Ca ion bình thường."},{"name":"Điện tim 12 chuyển đạo ngay sau khi có tuần hoàn tự phát","duration_minutes":10,"result":"ST chênh lên rõ ở V1 đến V5, nhịp xoang sau sốc."},{"name":"Siêu âm tim tại giường (không ngắt ép tim)","duration_minutes":15,"result":"Giảm động thành trước và vách; không tràn dịch màng tim."},{"name":"CT sọ và ngực trước khi sốc điện","duration_minutes":40,"result":"Không có chỉ định trong lúc ngừng tuần hoàn, làm chậm sốc điện."},{"name":"Chờ kết quả troponin rồi mới quyết định sốc điện","duration_minutes":10,"result":"Không liên quan quyết định xử trí rung thất."}],"choices":{"diagnosis":{"ydx":["Ngừng tuần hoàn do vô tâm thu","Ngừng tuần hoàn do rung thất, nghi nguyên nhân nhồi máu cơ tim cấp ST chênh lên","Thuyên tắc phổi gây hoạt động điện vô mạch","Ngất do phản xạ phế vị"]},"actions":["Dừng ép tim quá 10 giây để đặt nội khí quản","Xác nhận ngừng tuần hoàn, hô cứu hộ, lấy máy sốc điện và bắt đầu ép tim 100 đến 120 lần/phút, sâu 5 đến 6 cm","Chờ hoàn tất hội chẩn và chụp CT trước khi sốc điện","Dừng ép tim để bắt mạch nhiều lần giữa các chu kỳ","Tiêm atropine hoặc cho thở máy thông khí quá nhanh trong lúc ngừng tuần hoàn","Gắn máy sốc điện, sốc điện không đồng bộ 200 J (hai pha) ngay khi xác nhận rung thất, rồi ép tim lại ngay","Thông thoáng đường thở, thông khí bằng bóng mặt nạ oxy 100%, tỉ lệ 30 ép : 2 thổi cho đến khi đặt đường thở nâng cao","Tìm và xử trí nguyên nhân đảo ngược (thiếu oxy, thiếu thể tích, rối loạn điện giải, tắc mạch, tràn khí, chèn ép tim)","Thiết lập đường truyền tĩnh mạch hoặc trong xương, tiêm adrenalin 1 mg sau sốc lần 2 và lặp mỗi 3 đến 5 phút","Tiêm amiodarone 300 mg tĩnh mạch sau sốc lần 3 nếu còn rung thất, lần sau 150 mg","Sau khi có tuần hoàn tự phát: làm điện tim, duy trì SpO2 94 đến 98%, huyết áp trung bình trên 65 mmHg, kiểm soát thân nhiệt","Liên hệ can thiệp mạch vành khẩn khi có ST chênh lên"]}}'::jsonb,
  'db04ddfd93073fa9a7661f7af7cf00f041dff6038431f189867671967cfe0dd0'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-cap-cuu-001',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-001-1","resource_type":"other","source":"Bộ Y tế. Hướng dẫn quy trình hồi sinh tim phổi (cấp cứu ngừng tuần hoàn) cho người lớn, các quyết định liên quan cấp cứu, hồi sức tích cực và chống độc.","title":"Bộ Y tế. Hướng dẫn quy trình hồi sinh tim phổi (cấp cứu ngừng tuần hoàn) cho người lớn, các quyết định liên quan cấp cứu, hồi sức tích cực và chống độc.","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn quy trình hồi sinh tim phổi (cấp cứu ngừng tuần hoàn) cho người lớn, các quyết định liên quan cấp cứu, hồi sức tích cực và chống độc.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-als-aha-2025","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/41122884/","title":"American Heart Association. Guidelines for CPR and Emergency Cardiovascular Care, adult advanced cardiovascular life support, bản cập nhật gần nhất.","organization":null,"year_version":null,"citation":"American Heart Association. Guidelines for CPR and Emergency Cardiovascular Care, adult advanced cardiovascular life support, bản cập nhật gần nhất.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-als-erc-2025","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/41117572/","title":"European Resuscitation Council. Guidelines, Adult advanced life support, bản cập nhật gần nhất.","organization":null,"year_version":null,"citation":"European Resuscitation Council. Guidelines, Adult advanced life support, bản cập nhật gần nhất.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Ngừng tuần hoàn do rung thất, nghi nguyên nhân nhồi máu cơ tim cấp ST chênh lên","credit":"full"},{"text":"Ngất do phản xạ phế vị","credit":"none"},{"text":"Ngừng tuần hoàn do vô tâm thu","credit":"none"},{"text":"Thuyên tắc phổi gây hoạt động điện vô mạch","credit":"none"}]},"action_options":[{"text":"Xác nhận ngừng tuần hoàn, hô cứu hộ, lấy máy sốc điện và bắt đầu ép tim 100 đến 120 lần/phút, sâu 5 đến 6 cm","time_minutes":1,"grade":"critical","rationale":"Ngừng thở và mất mạch cảnh; ép tim ngay là ưu tiên đầu tiên."},{"text":"Gắn máy sốc điện, sốc điện không đồng bộ 200 J (hai pha) ngay khi xác nhận rung thất, rồi ép tim lại ngay","time_minutes":2,"grade":"critical","rationale":"Rung thất cần sốc sớm; mỗi phút chậm làm giảm cơ hội sống."},{"text":"Thông thoáng đường thở, thông khí bằng bóng mặt nạ oxy 100%, tỉ lệ 30 ép : 2 thổi cho đến khi đặt đường thở nâng cao","time_minutes":2,"grade":"critical","rationale":"Thiếu oxy tăng nhanh; đường thở đi cùng ép tim."},{"text":"Thiết lập đường truyền tĩnh mạch hoặc trong xương, tiêm adrenalin 1 mg sau sốc lần 2 và lặp mỗi 3 đến 5 phút","time_minutes":3,"grade":"critical","rationale":"Theo phác đồ hồi sinh tim phổi nâng cao."},{"text":"Tiêm amiodarone 300 mg tĩnh mạch sau sốc lần 3 nếu còn rung thất, lần sau 150 mg","time_minutes":3,"grade":"critical","rationale":"Rung thất kháng sốc."},{"text":"Tìm và xử trí nguyên nhân đảo ngược (thiếu oxy, thiếu thể tích, rối loạn điện giải, tắc mạch, tràn khí, chèn ép tim)","time_minutes":5,"grade":"recommended","rationale":"Duy trì vòng hồi sinh trong khi tìm nguyên nhân."},{"text":"Sau khi có tuần hoàn tự phát: làm điện tim, duy trì SpO2 94 đến 98%, huyết áp trung bình trên 65 mmHg, kiểm soát thân nhiệt","time_minutes":10,"grade":"recommended","rationale":"Chăm sóc sau ngừng tuần hoàn."},{"text":"Liên hệ can thiệp mạch vành khẩn khi có ST chênh lên","time_minutes":10,"grade":"recommended","rationale":"Nguyên nhân thường gặp của rung thất ở bệnh nhân này."},{"text":"Dừng ép tim quá 10 giây để đặt nội khí quản","time_minutes":3,"grade":"waste","rationale":"Làm giảm tưới máu vành và não; nên ép gần như liên tục."},{"text":"Chờ hoàn tất hội chẩn và chụp CT trước khi sốc điện","time_minutes":0,"grade":"harmful","rationale":"Rung thất không sốc sớm sẽ chuyển thành vô tâm thu."},{"text":"Dừng ép tim để bắt mạch nhiều lần giữa các chu kỳ","time_minutes":0,"grade":"harmful","rationale":"Làm gián đoạn tuần hoàn nhân tạo."},{"text":"Tiêm atropine hoặc cho thở máy thông khí quá nhanh trong lúc ngừng tuần hoàn","time_minutes":0,"grade":"harmful","rationale":"Không phải thuốc của rung thất; thông khí quá mức giảm hồi lưu tĩnh mạch."}],"teaching_explanation":"Rung thất là nhịp sốc được: ép tim chất lượng cao và sốc điện sớm quyết định sống còn. Adrenalin và amiodarone hỗ trợ sau sốc; luôn tìm nguyên nhân đảo ngược và chăm sóc sau ngừng tuần hoàn."}'::jsonb,
  '43261006bfbec2f7ab36f9a68912268786a4196c57f40c82a83652d66e4100f5'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt cao, tiểu buốt, lạnh run rồi tụt huyết áp, lú lẫn","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":68,"sex":"nữ","patient_label":"Bà N. T. H."},"presentation":{"intro":"Phòng cấp cứu. Người nữ lớn tuổi được con gái đưa vào vì sốt cao hai ngày, tiểu buốt, nay lạnh run, lú lẫn, người mệt lả.","place":null,"clock":null,"night":false},"vitals":{"hr":124,"sbp":78,"dbp":40,"rr":28,"temperature_c":39.6,"spo2":93},"history":[{"question":"Sốt từ khi nào, có lạnh run không?","response":"Sốt 2 ngày, rét run từ chiều qua."},{"question":"Triệu chứng tiết niệu: tiểu buốt, đau hông lưng, nước tiểu thế nào?","response":"Tiểu buốt, tiểu ít, nước tiểu đục, đau hông lưng phải."},{"question":"Ăn uống, lượng nước tiểu trong 12 giờ qua?","response":"Gần như không ăn, tiểu rất ít từ sáng."},{"question":"Bệnh nền: đái tháo đường, sỏi thận, ức chế miễn dịch?","response":"Đái tháo đường typ 2, từng sỏi thận, không dùng corticoid."},{"question":"Dị ứng thuốc, kháng sinh gần đây?","response":"Dị ứng penicillin dạng nổi mề đay; không dùng kháng sinh gần đây."},{"question":"Ho, đau bụng, tiêu chảy kèm theo?","response":"Không."},{"question":"Có đặt sonde tiểu hay can thiệp tiết niệu?","response":"Không."}],"examination":[{"group":"K","item":"Tri giác và tưới máu","finding":"Lơ mơ, Glasgow 13, chi lạnh, thời gian làm đầy mao mạch 5 giây, da nổi vân tím ở đầu gối."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều, phổi không ran, thở nhanh."},{"group":"K","item":"Khám thận","finding":"Rung thận phải đau rõ, góc sườn lưng phải ấn đau."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, không phản ứng thành bụng."},{"group":"K","item":"Da, vùng ống tĩnh mạch","finding":"Không vết loét, không áp xe da."}],"investigations":[{"name":"Lactate, khí máu động mạch","duration_minutes":10,"result":"Lactate 5,2 mmol/L; pH 7,28; HCO3 15 mmol/L."},{"name":"Cấy máu hai vị trí và cấy nước tiểu (không làm chậm kháng sinh)","duration_minutes":10,"result":"Đã lấy mẫu; chờ kết quả."},{"name":"Công thức máu, CRP, procalcitonin, creatinin, điện giải","duration_minutes":10,"result":"Bạch cầu 22 G/L; CRP 210 mg/L; creatinin 198 µmol/L; tiểu cầu 110 G/L."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Bạch cầu đầy, nitrit dương tính, nhiều vi khuẩn."},{"name":"Siêu âm thận tiết niệu khẩn","duration_minutes":15,"result":"Thận phải ứ nước độ II, sỏi niệu quản đoạn trên 8 mm."},{"name":"CT toàn thân có cản quang trước khi dùng kháng sinh","duration_minutes":40,"result":"Làm chậm kháng sinh; thuốc cản quang không cần thiết lúc chưa ổn định."},{"name":"Chờ kết quả cấy mới dùng kháng sinh","duration_minutes":10,"result":"Không được trì hoãn kháng sinh trong sốc nhiễm khuẩn."}],"choices":{"diagnosis":{"ydx":["Viêm bể thận không biến chứng","Sốc nhiễm khuẩn nguồn tiết niệu do sỏi niệu quản gây ứ nước, nhiễm khuẩn có tắc nghẽn","Sốc tim do nhồi máu cơ tim","Sốc phản vệ do thuốc"]},"actions":["Truyền dịch tinh thể cân bằng 30 mL/kg trong 3 giờ đầu, đánh giá đáp ứng bằng huyết áp, mao mạch, siêu âm","Cho kháng sinh uống và theo dõi ngoại trú","Chờ có kết quả cấy mới bắt đầu kháng sinh","Đánh giá ABC, thở oxy, gắn monitor, lập 2 đường truyền, lấy máu lactate và cấy máu","Đặt sonde tiểu theo dõi nước tiểu, theo dõi lactate lặp lại sau 2 đến 4 giờ","Dùng corticoid liều cao ngay từ đầu cho mọi trường hợp","Hội chẩn tiết niệu để giải áp đường tiết niệu khẩn","Dùng noradrenalin khi huyết áp trung bình dưới 65 mmHg sau truyền dịch, đặt catheter tĩnh mạch trung tâm khi cần","Truyền dịch lượng lớn nhanh không theo dõi dù xuất hiện ran phổi, thiếu oxy","Kháng sinh tĩnh mạch phổ rộng, chọn thuốc phù hợp tiền sử dị ứng penicillin (ví dụ nhóm carbapenem hoặc phác đồ theo hướng dẫn tại chỗ), trong 1 giờ đầu"]}}'::jsonb,
  '709762fab3831ae35975b3f53c146fb3a2b0748922ae0d0a9572373aa54fed62'
)
on conflict (case_id) do update set
