values (
  'noi-cap-cuu-002',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-002-1","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị nhiễm khuẩn huyết và sốc nhiễm khuẩn; Hướng dẫn quy trình hồi sức cấp cứu.","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị nhiễm khuẩn huyết và sốc nhiễm khuẩn; Hướng dẫn quy trình hồi sức cấp cứu.","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị nhiễm khuẩn huyết và sốc nhiễm khuẩn; Hướng dẫn quy trình hồi sức cấp cứu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-sepsis-ssc-2021-ac318ed1a46d","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/34605781/","title":"Surviving Sepsis Campaign. International Guidelines for Management of Sepsis and Septic Shock 2021. DOI: 10.1097/CCM.0000000000005337.","organization":null,"year_version":null,"citation":"Surviving Sepsis Campaign. International Guidelines for Management of Sepsis and Septic Shock 2021. DOI: 10.1097/CCM.0000000000005337.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-002-3","resource_type":"other","source":"Hội Tiết niệu Thận học Việt Nam. Hướng dẫn xử trí nhiễm khuẩn tiết niệu có tắc nghẽn.","title":"Hội Tiết niệu Thận học Việt Nam. Hướng dẫn xử trí nhiễm khuẩn tiết niệu có tắc nghẽn.","organization":null,"year_version":null,"citation":"Hội Tiết niệu Thận học Việt Nam. Hướng dẫn xử trí nhiễm khuẩn tiết niệu có tắc nghẽn.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Sốc tim do nhồi máu cơ tim","credit":"none"},{"text":"Sốc phản vệ do thuốc","credit":"none"},{"text":"Sốc nhiễm khuẩn nguồn tiết niệu do sỏi niệu quản gây ứ nước, nhiễm khuẩn có tắc nghẽn","credit":"full"},{"text":"Viêm bể thận không biến chứng","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, thở oxy, gắn monitor, lập 2 đường truyền, lấy máu lactate và cấy máu","time_minutes":3,"grade":"critical","rationale":"Nhận diện sốc nhiễm khuẩn và bắt đầu gói hồi sức giờ đầu."},{"text":"Kháng sinh tĩnh mạch phổ rộng, chọn thuốc phù hợp tiền sử dị ứng penicillin (ví dụ nhóm carbapenem hoặc phác đồ theo hướng dẫn tại chỗ), trong 1 giờ đầu","time_minutes":5,"grade":"critical","rationale":"Mỗi giờ chậm kháng sinh làm tăng tử vong."},{"text":"Truyền dịch tinh thể cân bằng 30 mL/kg trong 3 giờ đầu, đánh giá đáp ứng bằng huyết áp, mao mạch, siêu âm","time_minutes":5,"grade":"critical","rationale":"Hồi sức thể tích ban đầu theo khuyến cáo."},{"text":"Dùng noradrenalin khi huyết áp trung bình dưới 65 mmHg sau truyền dịch, đặt catheter tĩnh mạch trung tâm khi cần","time_minutes":10,"grade":"critical","rationale":"Duy trì tưới máu cơ quan."},{"text":"Hội chẩn tiết niệu để giải áp đường tiết niệu khẩn","time_minutes":10,"grade":"critical","rationale":"Kiểm soát nguồn nhiễm khuẩn là then chốt."},{"text":"Đặt sonde tiểu theo dõi nước tiểu, theo dõi lactate lặp lại sau 2 đến 4 giờ","time_minutes":10,"grade":"recommended","rationale":"Đánh giá đáp ứng hồi sức."},{"text":"Dùng corticoid liều cao ngay từ đầu cho mọi trường hợp","time_minutes":5,"grade":"waste","rationale":"Chỉ cân nhắc hydrocortisone khi sốc kháng thuốc vận mạch kéo dài."},{"text":"Chờ có kết quả cấy mới bắt đầu kháng sinh","time_minutes":0,"grade":"harmful","rationale":"Làm chậm điều trị, tăng nguy cơ tử vong."},{"text":"Truyền dịch lượng lớn nhanh không theo dõi dù xuất hiện ran phổi, thiếu oxy","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ quá tải dịch, phù phổi."},{"text":"Cho kháng sinh uống và theo dõi ngoại trú","time_minutes":0,"grade":"harmful","rationale":"Bệnh nhân đang sốc, suy cơ quan."}],"teaching_explanation":"Sốc nhiễm khuẩn cần kháng sinh trong giờ đầu, hồi sức dịch có đánh giá và vận mạch sớm. Nếu nguồn là tắc nghẽn đường tiết niệu, kiểm soát nguồn (giải áp) không kém quan trọng kháng sinh."}'::jsonb,
