insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Co giật toàn thân kéo dài hơn 10 phút, chưa tỉnh lại","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":32,"sex":"nam","patient_label":"Anh P. Q. K."},"presentation":{"intro":"Phòng cấp cứu. Người nhà đưa vào người đàn ông co giật toàn thân liên tục khoảng 12 phút, mắt trợn ngược, sùi bọt mép. Đã quá 5 phút khi đến nơi.","place":null,"clock":null,"night":false},"vitals":{"hr":132,"sbp":164,"dbp":96,"rr":30,"temperature_c":38.2,"spo2":84},"history":[{"question":"Cơn co giật bắt đầu lúc nào, kéo dài bao lâu, có tỉnh giữa các cơn không?","response":"Bắt đầu 12 phút trước, co giật liên tục, chưa tỉnh lại."},{"question":"Tiền sử động kinh, thuốc chống động kinh, bỏ thuốc?","response":"Động kinh 5 năm, uống thuốc chống động kinh nhưng tự bỏ thuốc 1 tuần nay."},{"question":"Chấn thương đầu, sốt, đau đầu trước đó?","response":"Không chấn thương, sốt nhẹ từ hôm qua."},{"question":"Uống rượu, ma túy, ngộ độc?","response":"Có uống rượu tối qua, không dùng ma túy."},{"question":"Đái tháo đường, hạ đường huyết?","response":"Không đái tháo đường."},{"question":"Dị ứng thuốc, bệnh nền khác?","response":"Không dị ứng."},{"question":"Ăn uống nôn trước đó?","response":"Có nôn một lần trước khi co giật."}],"examination":[{"group":"K","item":"Đường thở và thông khí","finding":"Ngáy, tiết bọt đờm, tím quanh môi, thở nhanh."},{"group":"K","item":"Thần kinh","finding":"Co cứng co giật toàn thân, mắt đảo, đồng tử 4 mm, phản xạ ánh sáng chậm."},{"group":"K","item":"Dấu màng não","finding":"Cứng gáy không đánh giá được do co giật."},{"group":"K","item":"Dấu chấn thương đầu","finding":"Không có vết thương, không máu tai mũi."},{"group":"K","item":"Tim phổi","finding":"Nhịp nhanh, phổi thô nhẹ, nghi hít sặc."}],"investigations":[{"name":"Đường huyết mao mạch ngay lập tức","duration_minutes":10,"result":"Đường huyết 5,6 mmol/L."},{"name":"Điện giải đồ, canxi, magie, ure, creatinin","duration_minutes":10,"result":"Natri 138; canxi 2,2; magie 0,8 mmol/L."},{"name":"Khí máu động mạch, lactate","duration_minutes":10,"result":"pH 7,12; lactate 12 mmol/L."},{"name":"Nồng độ thuốc chống động kinh trong máu","duration_minutes":10,"result":"Dưới ngưỡng điều trị."},{"name":"Chụp CT sọ não không cản quang khi ổn định co giật","duration_minutes":40,"result":"Không xuất huyết, không khối choán chỗ."},{"name":"Chọc dò dịch não tủy ngay khi đang co giật","duration_minutes":10,"result":"Không an toàn và không ưu tiên khi chưa kiểm soát cơn."},{"name":"Điện não đồ trước khi xử trí cắt cơn","duration_minutes":10,"result":"Không chờ điện não đồ để điều trị cắt cơn."}],"choices":{"diagnosis":{"ydx":["Cơn ngất co giật đơn thuần","Trạng thái động kinh co giật toàn thể do bỏ thuốc chống động kinh","Cơn co giật do hạ đường huyết","Cơn co giật do tâm lý"]},"actions":["Cho phenytoin truyền nhanh khi chưa đo điện tim","Chỉ theo dõi, chờ cơn tự ngừng trong khi SpO2 84%","Diazepam 10 mg tiêm tĩnh mạch chậm, lặp lại 1 lần nếu còn co giật (hoặc midazolam 10 mg tiêm bắp liều đơn nếu chưa có đường truyền)","Tiêm benzodiazepin liều lớn liên tục không hỗ trợ thông khí","Chuẩn bị đặt nội khí quản và gây mê (propofol hoặc midazolam truyền) nếu trạng thái động kinh kháng trị","Nếu còn co giật sau 2 liều: levetiracetam 60 mg/kg (tối đa 4500 mg) truyền tĩnh mạch hoặc valproate 40 mg/kg","Kiểm tra đường huyết mao mạch và lập đường truyền tĩnh mạch","Đặt nằm nghiêng an toàn, hút đờm, thở oxy cao lưu lượng, gắn monitor, bóp bóng hỗ trợ nếu SpO2 thấp","Nhét vật cứng hoặc ngáng lưỡi vào miệng","Tìm nguyên nhân: CT sọ, xét nghiệm, cân nhắc chọc dò dịch não tủy khi sốt kèm cứng gáy"]}}'::jsonb,
  '432a9b7e66c6b4ba0eb8cf508cb576a77318798706277bda1153d222091c4ed7'
)
