values (
  'noi-cap-cuu-003',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-003-1","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị động kinh; Hướng dẫn quy trình cấp cứu trạng thái động kinh.","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị động kinh; Hướng dẫn quy trình cấp cứu trạng thái động kinh.","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị động kinh; Hướng dẫn quy trình cấp cứu trạng thái động kinh.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-se-aes-2016","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/26900382/","title":"American Epilepsy Society. Guideline for the treatment of convulsive status epilepticus in children and adults, Epilepsy Curr 2016;16(1):48-61. DOI: 10.5698/1535-7597-16.1.48.","organization":null,"year_version":null,"citation":"American Epilepsy Society. Guideline for the treatment of convulsive status epilepticus in children and adults, Epilepsy Curr 2016;16(1):48-61. DOI: 10.5698/1535-7597-16.1.48.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-003-3","resource_type":"other","source":"Hội Thần kinh học Việt Nam. Khuyến cáo xử trí trạng thái động kinh.","title":"Hội Thần kinh học Việt Nam. Khuyến cáo xử trí trạng thái động kinh.","organization":null,"year_version":null,"citation":"Hội Thần kinh học Việt Nam. Khuyến cáo xử trí trạng thái động kinh.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Cơn co giật do hạ đường huyết","credit":"none"},{"text":"Trạng thái động kinh co giật toàn thể do bỏ thuốc chống động kinh","credit":"full"},{"text":"Cơn co giật do tâm lý","credit":"none"},{"text":"Cơn ngất co giật đơn thuần","credit":"none"}]},"action_options":[{"text":"Đặt nằm nghiêng an toàn, hút đờm, thở oxy cao lưu lượng, gắn monitor, bóp bóng hỗ trợ nếu SpO2 thấp","time_minutes":2,"grade":"critical","rationale":"Thiếu oxy nặng là ưu tiên ABC đầu tiên."},{"text":"Kiểm tra đường huyết mao mạch và lập đường truyền tĩnh mạch","time_minutes":2,"grade":"critical","rationale":"Loại trừ hạ đường huyết, lấy máu xét nghiệm."},{"text":"Diazepam 10 mg tiêm tĩnh mạch chậm, lặp lại 1 lần nếu còn co giật (hoặc midazolam 10 mg tiêm bắp liều đơn nếu chưa có đường truyền)","time_minutes":3,"grade":"critical","rationale":"Benzodiazepin là thuốc bậc 1 trong trạng thái động kinh."},{"text":"Nếu còn co giật sau 2 liều: levetiracetam 60 mg/kg (tối đa 4500 mg) truyền tĩnh mạch hoặc valproate 40 mg/kg","time_minutes":10,"grade":"critical","rationale":"Thuốc bậc 2 cho trạng thái động kinh."},{"text":"Chuẩn bị đặt nội khí quản và gây mê (propofol hoặc midazolam truyền) nếu trạng thái động kinh kháng trị","time_minutes":15,"grade":"critical","rationale":"Bậc 3 khi thất bại điều trị hai bậc đầu."},{"text":"Tìm nguyên nhân: CT sọ, xét nghiệm, cân nhắc chọc dò dịch não tủy khi sốt kèm cứng gáy","time_minutes":20,"grade":"recommended","rationale":"Sốt nhẹ cần loại trừ nhiễm khuẩn thần kinh."},{"text":"Cho phenytoin truyền nhanh khi chưa đo điện tim","time_minutes":3,"grade":"waste","rationale":"Nguy cơ loạn nhịp, hạ huyết áp."},{"text":"Nhét vật cứng hoặc ngáng lưỡi vào miệng","time_minutes":0,"grade":"harmful","rationale":"Gây tổn thương răng, tắc đường thở."},{"text":"Chỉ theo dõi, chờ cơn tự ngừng trong khi SpO2 84%","time_minutes":0,"grade":"harmful","rationale":"Cơn kéo dài trên 5 phút cần dùng thuốc ngay."},{"text":"Tiêm benzodiazepin liều lớn liên tục không hỗ trợ thông khí","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ ngừng thở."}],"teaching_explanation":"Co giật kéo dài trên 5 phút là trạng thái động kinh: bảo đảm ABC, kiểm tra đường huyết và dùng benzodiazepin sớm. Thuốc bậc 2 và bậc 3 theo sau; luôn tìm nguyên nhân thúc đẩy."}'::jsonb,
