insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-004',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khát nhiều, tiểu nhiều nhiều ngày, nay lơ mơ, mất nước nặng","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":66,"sex":"nam","patient_label":"Ông H. V. D."},"presentation":{"intro":"Phòng cấp cứu. Người con đưa cha vào vì mệt lả, khát và tiểu nhiều vài ngày, nay lơ mơ, nói lẫn.","place":null,"clock":null,"night":false},"vitals":{"hr":116,"sbp":92,"dbp":54,"rr":22,"temperature_c":37.8,"spo2":96},"history":[{"question":"Khát, tiểu nhiều kéo dài bao lâu?","response":"Khoảng 1 tuần, uống nhiều nước nhưng vẫn khát."},{"question":"Tiền sử đái tháo đường, thuốc đang dùng?","response":"Đái tháo đường typ 2, uống metformin, đôi khi quên thuốc."},{"question":"Lý do khởi phát: nhiễm khuẩn, bỏ thuốc, uống nước ngọt nhiều?","response":"Hôm trước bị ho, sốt nhẹ, ăn kém."},{"question":"Nôn, đau bụng, thở sâu?","response":"Không nôn, không đau bụng, không thở sâu."},{"question":"Tiền sử tim, thận, suy tim?","response":"Không suy tim, thận bình thường."},{"question":"Dị ứng thuốc?","response":"Không."},{"question":"Có dùng corticoid hay lợi tiểu?","response":"Không."}],"examination":[{"group":"K","item":"Tri giác","finding":"Lơ mơ, Glasgow 12, trả lời lẫn."},{"group":"K","item":"Mất nước","finding":"Da khô, niêm khô, nếp véo da mất chậm, mắt trũng."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh, phổi trong, không ran."},{"group":"K","item":"Hơi thở","finding":"Nhịp thở bình thường, không mùi ceton."},{"group":"K","item":"Thần kinh","finding":"Không liệt khu trú, không cứng gáy."}],"investigations":[{"name":"Đường huyết mao mạch và đường huyết tĩnh mạch","duration_minutes":10,"result":"Đường huyết 48 mmol/L."},{"name":"Ceton máu hoặc nước tiểu","duration_minutes":10,"result":"Ceton máu 0,6 mmol/L (thấp)."},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,34; HCO3 21 mmol/L."},{"name":"Điện giải đồ, ure, creatinin, thẩm thấu","duration_minutes":10,"result":"Natri đo 148, natri hiệu chỉnh 160 mmol/L; kali 4,8; ure 22 mmol/L; thẩm thấu tính toán 390 mOsm/kg."},{"name":"Công thức máu, CRP, X quang ngực, tổng phân tích nước tiểu tìm yếu tố khởi phát","duration_minutes":10,"result":"Bạch cầu 15 G/L; X quang ngực viêm phổi thùy dưới phải nhẹ."},{"name":"CT sọ não khẩn trước khi bù dịch","duration_minutes":40,"result":"Không có dấu thần kinh khu trú, không ưu tiên khi chưa hồi sức dịch."},{"name":"Chọc dò dịch não tủy","duration_minutes":10,"result":"Không có dấu hiệu màng não, không chỉ định."}],"choices":{"diagnosis":{"ydx":["Đột quỵ não là nguyên nhân duy nhất","Hạ đường huyết do thuốc","Nhiễm toan ceton đái tháo đường điển hình","Tình trạng tăng đường huyết tăng thẩm thấu, nguy cơ do viêm phổi"]},"actions":["Truyền NaCl 0,9% hoặc dịch tinh thể cân bằng 500 đến 1000 mL/giờ trong 2 đến 4 giờ đầu (người lớn không suy tim, suy thận), sau đó điều chỉnh theo natri hiệu chỉnh và huyết động","Đo đường huyết mao mạch mỗi 1 đến 2 giờ, điện giải mỗi 4 giờ, thêm dextrose 5 đến 10% khi đường huyết dưới 13,9 mmol/L","Cho dung dịch glucose 5% làm dịch bù ban đầu","Dự phòng huyết khối tĩnh mạch sâu theo nguy cơ","Đánh giá ABC, gắn monitor, lập 2 đường truyền tĩnh mạch, lấy máu xét nghiệm","Giảm đường huyết quá nhanh bằng insulin liều rất cao","Kiểm tra kali trước khi dùng insulin; chỉ khởi insulin truyền tĩnh mạch cố định (0,05 đến 0,1 UI/kg/giờ tùy bệnh cảnh) khi kali trên 3,5 mmol/L","Điều trị yếu tố khởi phát: kháng sinh cho viêm phổi sau cấy máu","Bù kali khi kali dưới 5,0 mmol/L và có nước tiểu","Cho metformin uống ngay trong cấp cứu","Hạ đường huyết nhanh bằng bolus insulin lớn mà không bù dịch"]}}'::jsonb,
  '1c9f795caea297491ecdcff5b459c307fda553da3f66f4e96d00213c6c4c69ee'
)
