  'noi-cap-cuu-004',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-004-1","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị đái tháo đường typ 2 (phần xử trí biến chứng cấp tính); Hướng dẫn quy trình chăm sóc, điều trị cấp cứu hôn mê tăng thẩm thấu.","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị đái tháo đường typ 2 (phần xử trí biến chứng cấp tính); Hướng dẫn quy trình chăm sóc, điều trị cấp cứu hôn mê tăng thẩm thấu.","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị đái tháo đường typ 2 (phần xử trí biến chứng cấp tính); Hướng dẫn quy trình chăm sóc, điều trị cấp cứu hôn mê tăng thẩm thấu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-dka-ada-2024-439d81c681e1","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/39052901/","title":"American Diabetes Association and consensus report. Hyperglycemic crises in adults with diabetes. Diabetes Care 2024;47:1257-1275. DOI: 10.2337/dci24-0032.","organization":null,"year_version":null,"citation":"American Diabetes Association and consensus report. Hyperglycemic crises in adults with diabetes. Diabetes Care 2024;47:1257-1275. DOI: 10.2337/dci24-0032.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-004-3","resource_type":"other","source":"Hội Nội tiết và Đái tháo đường Việt Nam. Khuyến cáo xử trí biến chứng cấp tính đái tháo đường.","title":"Hội Nội tiết và Đái tháo đường Việt Nam. Khuyến cáo xử trí biến chứng cấp tính đái tháo đường.","organization":null,"year_version":null,"citation":"Hội Nội tiết và Đái tháo đường Việt Nam. Khuyến cáo xử trí biến chứng cấp tính đái tháo đường.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đột quỵ não là nguyên nhân duy nhất","credit":"none"},{"text":"Tình trạng tăng đường huyết tăng thẩm thấu, nguy cơ do viêm phổi","credit":"full"},{"text":"Hạ đường huyết do thuốc","credit":"none"},{"text":"Nhiễm toan ceton đái tháo đường điển hình","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, gắn monitor, lập 2 đường truyền tĩnh mạch, lấy máu xét nghiệm","time_minutes":2,"grade":"critical","rationale":"Người bệnh lơ mơ, mất nước nặng."},{"text":"Truyền NaCl 0,9% hoặc dịch tinh thể cân bằng 500 đến 1000 mL/giờ trong 2 đến 4 giờ đầu (người lớn không suy tim, suy thận), sau đó điều chỉnh theo natri hiệu chỉnh và huyết động","time_minutes":5,"grade":"critical","rationale":"Bù thể tích là ưu tiên đầu tiên trong tăng đường huyết tăng thẩm thấu."},{"text":"Kiểm tra kali trước khi dùng insulin; chỉ khởi insulin truyền tĩnh mạch cố định (0,05 đến 0,1 UI/kg/giờ tùy bệnh cảnh) khi kali trên 3,5 mmol/L","time_minutes":10,"grade":"critical","rationale":"Insulin sớm khi chưa bù dịch làm tụt huyết áp và hạ kali."},{"text":"Bù kali khi kali dưới 5,0 mmol/L và có nước tiểu","time_minutes":10,"grade":"critical","rationale":"Insulin kéo kali vào tế bào."},{"text":"Điều trị yếu tố khởi phát: kháng sinh cho viêm phổi sau cấy máu","time_minutes":10,"grade":"critical","rationale":"Yếu tố khởi phát thường gặp."},{"text":"Đo đường huyết mao mạch mỗi 1 đến 2 giờ, điện giải mỗi 4 giờ, thêm dextrose 5 đến 10% khi đường huyết dưới 13,9 mmol/L","time_minutes":15,"grade":"recommended","rationale":"Tránh hạ đường huyết, phù não."},{"text":"Dự phòng huyết khối tĩnh mạch sâu theo nguy cơ","time_minutes":20,"grade":"recommended","rationale":"Tăng độ quánh máu và bất động."},{"text":"Giảm đường huyết quá nhanh bằng insulin liều rất cao","time_minutes":3,"grade":"waste","rationale":"Giảm thẩm thấu nhanh gây phù não."},{"text":"Hạ đường huyết nhanh bằng bolus insulin lớn mà không bù dịch","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ sốc, hạ kali."},{"text":"Cho dung dịch glucose 5% làm dịch bù ban đầu","time_minutes":0,"grade":"harmful","rationale":"Làm nặng thêm tăng đường huyết và tăng thẩm thấu."},{"text":"Cho metformin uống ngay trong cấp cứu","time_minutes":0,"grade":"harmful","rationale":"Không dùng thuốc uống khi lơ mơ, nguy cơ toan lactate."}],"teaching_explanation":"Tăng đường huyết tăng thẩm thấu cần bù dịch trước, insulin sau khi kali ổn, hạ thẩm thấu chậm. Luôn tìm yếu tố khởi phát như nhiễm khuẩn."}'::jsonb,
  'c09718018db9503e0783a86bf33d569579a09e63304d7dfaf271b14bc8f286dd'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-005',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-005","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Yếu liệt chi, mệt lả ở người suy thận bỏ lọc máu, điện tim nhịp chậm","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":61,"sex":"nam","patient_label":"Ông T. C. B."},"presentation":{"intro":"Phòng cấp cứu. Người suy thận mạn lọc máu chu kỳ bỏ hai buổi lọc, nay yếu hai chân, hồi hộp, mệt lả.","place":null,"clock":null,"night":false},"vitals":{"hr":42,"sbp":88,"dbp":52,"rr":20,"temperature_c":36.6,"spo2":95},"history":[{"question":"Bỏ lọc máu từ bao giờ?","response":"Đã bỏ hai buổi liên tiếp, gần 8 ngày chưa lọc."},{"question":"Triệu chứng hiện tại: yếu cơ, hồi hộp, ngất?","response":"Yếu hai chân tăng dần, tim đập chậm, hoa mắt."},{"question":"Ăn uống: trái cây nhiều kali, thuốc đang dùng?","response":"Ăn nhiều chuối, uống nước dừa; dùng thuốc ức chế men chuyển và spironolactone."},{"question":"Tiểu ít, phù, khó thở?","response":"Tiểu rất ít, phù chân nhẹ."},{"question":"Dị ứng thuốc, bệnh tim?","response":"Không dị ứng; tăng huyết áp, không bệnh mạch vành."},{"question":"Dùng thuốc ức chế beta, digoxin?","response":"Không."},{"question":"Tiêu chảy, nôn mất nước?","response":"Không."}],"examination":[{"group":"K","item":"Mạch và huyết áp","finding":"Mạch chậm khoảng 42 lần/phút, huyết áp thấp."},{"group":"K","item":"Thần kinh cơ","finding":"Yếu hai chân 3/5, phản xạ gân xương giảm."},{"group":"K","item":"Tim phổi","finding":"Nhịp chậm đều, phổi trong."},{"group":"K","item":"Phù và tưới máu","finding":"Phù chân nhẹ, chi hơi lạnh."},{"group":"K","item":"Đường thở","finding":"Thông, nói rõ."}],"investigations":[{"name":"Điện tim 12 chuyển đạo","duration_minutes":10,"result":"Sóng T cao nhọn, QRS giãn rộng 140 ms, mất sóng P, nhịp bộ nối chậm."},{"name":"Kali máu (khí máu cho kết quả nhanh)","duration_minutes":10,"result":"Kali 7,9 mmol/L."},{"name":"Ure, creatinin, khí máu động mạch","duration_minutes":10,"result":"Creatinin 1100 µmol/L; pH 7,18; HCO3 12 mmol/L."},{"name":"Đường huyết mao mạch","duration_minutes":10,"result":"Đường huyết 6,2 mmol/L."},{"name":"Canxi, magie, phospho","duration_minutes":10,"result":"Canxi 2,0 mmol/L; phospho cao."},{"name":"CT ngực khẩn trước khi xử trí","duration_minutes":40,"result":"Không phù hợp khi chưa ổn định, làm chậm xử trí."},{"name":"Chờ kết quả cấy máu rồi mới điều trị","duration_minutes":10,"result":"Không liên quan, trì hoãn điều trị."}],"choices":{"diagnosis":{"ydx":["Hạ kali máu","Ngộ độc digoxin","Nhồi máu cơ tim cấp thành dưới","Tăng kali máu nặng có thay đổi điện tim, nhịp chậm, nhiễm toan chuyển hóa trên người suy thận bỏ lọc"]},"actions":["Hội chẩn thận nhân tạo, chuẩn bị lọc máu cấp cứu","Salbutamol khí dung 10 đến 20 mg","Canxi gluconat 10% 30 mL (hoặc canxi clorua 10% 10 mL) tiêm tĩnh mạch chậm trong 5 đến 10 phút, lặp lại sau 5 phút nếu QRS còn giãn","Natri bicarbonat 50 mmol truyền tĩnh mạch khi nhiễm toan nặng","Gắn monitor, thở oxy, lập đường truyền, lấy máu kali và khí máu","Insulin thường 10 UI kèm glucose 50% 50 mL (25 g) tĩnh mạch, theo dõi đường huyết","Truyền dung dịch Ringer lactat lượng lớn và kali","Ngừng thuốc ức chế men chuyển, spironolactone và thực phẩm giàu kali, theo dõi điện tim liên tục","Chờ có kết quả kali lần hai rồi mới dùng canxi khi QRS đã giãn rộng","Tiêm tĩnh mạch nhanh canxi trong 10 giây hoặc trộn với bicarbonat cùng đường","Dùng furosemide đơn độc khi bệnh nhân vô niệu"]}}'::jsonb,
  '79f6a2a27d7d70845001a0aaad1efbfaf068f17c4561321f879ea37e71464f1a'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
