values (
  'noi-cap-cuu-005',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-005","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-005-1","resource_type":"other","source":"Bộ Y tế. Hướng dẫn quy trình kỹ thuật và xử trí rối loạn điện giải (tăng kali máu) trong hồi sức cấp cứu; Hướng dẫn chẩn đoán và điều trị bệnh thận mạn.","title":"Bộ Y tế. Hướng dẫn quy trình kỹ thuật và xử trí rối loạn điện giải (tăng kali máu) trong hồi sức cấp cứu; Hướng dẫn chẩn đoán và điều trị bệnh thận mạn.","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn quy trình kỹ thuật và xử trí rối loạn điện giải (tăng kali máu) trong hồi sức cấp cứu; Hướng dẫn chẩn đoán và điều trị bệnh thận mạn.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ukka-hyperkalaemia-fef384dbb02e","resource_type":"guideline","source":"https://ukkidney.org/guidelines/joint-guidelines/treatment-of-acute-hyperkalaemia-in-adults","title":"UK Kidney Association. Clinical Practice Guidelines: Treatment of Acute Hyperkalaemia in Adults, bản 2023.","organization":null,"year_version":null,"citation":"UK Kidney Association. Clinical Practice Guidelines: Treatment of Acute Hyperkalaemia in Adults, bản 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-005-3","resource_type":"other","source":"Hội Thận học Việt Nam. Khuyến cáo xử trí cấp cứu tăng kali máu.","title":"Hội Thận học Việt Nam. Khuyến cáo xử trí cấp cứu tăng kali máu.","organization":null,"year_version":null,"citation":"Hội Thận học Việt Nam. Khuyến cáo xử trí cấp cứu tăng kali máu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Ngộ độc digoxin","credit":"none"},{"text":"Tăng kali máu nặng có thay đổi điện tim, nhịp chậm, nhiễm toan chuyển hóa trên người suy thận bỏ lọc","credit":"full"},{"text":"Nhồi máu cơ tim cấp thành dưới","credit":"none"},{"text":"Hạ kali máu","credit":"none"}]},"action_options":[{"text":"Gắn monitor, thở oxy, lập đường truyền, lấy máu kali và khí máu","time_minutes":2,"grade":"critical","rationale":"Đánh giá ABC, nhịp chậm kèm huyết áp thấp."},{"text":"Canxi gluconat 10% 30 mL (hoặc canxi clorua 10% 10 mL) tiêm tĩnh mạch chậm trong 5 đến 10 phút, lặp lại sau 5 phút nếu QRS còn giãn","time_minutes":3,"grade":"critical","rationale":"Ổn định màng tế bào cơ tim, ưu tiên khi có thay đổi điện tim."},{"text":"Insulin thường 10 UI kèm glucose 50% 50 mL (25 g) tĩnh mạch, theo dõi đường huyết","time_minutes":5,"grade":"critical","rationale":"Đưa kali vào trong tế bào, tác dụng sau khoảng 15 đến 30 phút."},{"text":"Salbutamol khí dung 10 đến 20 mg","time_minutes":5,"grade":"critical","rationale":"Hiệp đồng kéo kali vào tế bào."},{"text":"Natri bicarbonat 50 mmol truyền tĩnh mạch khi nhiễm toan nặng","time_minutes":10,"grade":"critical","rationale":"Hỗ trợ khi pH thấp."},{"text":"Hội chẩn thận nhân tạo, chuẩn bị lọc máu cấp cứu","time_minutes":10,"grade":"recommended","rationale":"Cách loại bỏ kali ra khỏi cơ thể ở bệnh nhân vô niệu."},{"text":"Ngừng thuốc ức chế men chuyển, spironolactone và thực phẩm giàu kali, theo dõi điện tim liên tục","time_minutes":10,"grade":"recommended","rationale":"Loại bỏ yếu tố làm tăng kali."},{"text":"Dùng furosemide đơn độc khi bệnh nhân vô niệu","time_minutes":5,"grade":"waste","rationale":"Không hiệu quả khi không còn nước tiểu."},{"text":"Truyền dung dịch Ringer lactat lượng lớn và kali","time_minutes":0,"grade":"harmful","rationale":"Làm tăng thêm kali."},{"text":"Tiêm tĩnh mạch nhanh canxi trong 10 giây hoặc trộn với bicarbonat cùng đường","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ ngừng tim, kết tủa."},{"text":"Chờ có kết quả kali lần hai rồi mới dùng canxi khi QRS đã giãn rộng","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ rối loạn nhịp ác tính."}],"teaching_explanation":"Tăng kali nặng có biến đổi điện tim cần canxi tĩnh mạch ngay, sau đó kéo kali vào tế bào và thải kali (lọc máu). Không chờ kết quả lặp."}'::jsonb,
