insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-006',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-006","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Ngất, chóng mặt, mạch rất chậm, huyết áp thấp","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":74,"sex":"nữ","patient_label":"Bà V. T. N."},"presentation":{"intro":"Phòng cấp cứu. Người nữ lớn tuổi ngất hai lần trong buổi sáng, hoa mắt, mệt, đến cấp cứu với mạch chậm và huyết áp thấp.","place":null,"clock":null,"night":false},"vitals":{"hr":32,"sbp":80,"dbp":46,"rr":22,"temperature_c":36.5,"spo2":92},"history":[{"question":"Ngất mấy lần, trong tình huống nào?","response":"Ngất hai lần, khi đang đi và khi đứng dậy, tỉnh lại sau vài chục giây."},{"question":"Triệu chứng kèm theo: đau ngực, khó thở, hồi hộp?","response":"Mệt, khó thở nhẹ, hơi tức ngực."},{"question":"Thuốc đang dùng: chẹn beta, chẹn kênh canxi, digoxin?","response":"Mới tăng liều thuốc chẹn beta tuần trước, đang uống amlodipine."},{"question":"Bệnh tim, tăng huyết áp, đái tháo đường?","response":"Tăng huyết áp nhiều năm, bệnh mạch vành đã đặt stent."},{"question":"Dị ứng thuốc?","response":"Không."},{"question":"Sốt, viêm gần đây, bệnh Lyme?","response":"Không."},{"question":"Tiền sử đột quỵ?","response":"Không."}],"examination":[{"group":"K","item":"Mạch và nhịp tim","finding":"Mạch 32 lần/phút đều, T1 thay đổi cường độ."},{"group":"K","item":"Tưới máu và tri giác","finding":"Tỉnh, vã mồ hôi, da lạnh ẩm, thời gian đổ đầy mao mạch 4 giây."},{"group":"K","item":"Phổi","finding":"Ran ẩm hai đáy phổi."},{"group":"K","item":"Tĩnh mạch cổ","finding":"Sóng đại bác ở tĩnh mạch cổ thỉnh thoảng thấy."},{"group":"K","item":"Thần kinh","finding":"Không dấu thần kinh khu trú."}],"investigations":[{"name":"Điện tim 12 chuyển đạo","duration_minutes":10,"result":"Sóng P đều 80 lần/phút, QRS rộng 130 ms, tần số thất 32 lần/phút, P và QRS phân ly hoàn toàn."},{"name":"Điện giải đồ, đặc biệt kali","duration_minutes":10,"result":"Kali 4,2 mmol/L."},{"name":"Troponin hs và men tim lặp lại","duration_minutes":10,"result":"Troponin tăng nhẹ."},{"name":"Khí máu động mạch và lactate","duration_minutes":10,"result":"Lactate 2,8 mmol/L."},{"name":"Siêu âm tim tại giường","duration_minutes":15,"result":"Phân suất tống máu 45%, giảm động thành dưới."},{"name":"CT sọ não trước khi xử trí","duration_minutes":40,"result":"Không có dấu thần kinh khu trú, không cần chờ."},{"name":"Test gắng sức chẩn đoán","duration_minutes":10,"result":"Chống chỉ định khi đang block nhĩ thất độ III có triệu chứng."}],"choices":{"diagnosis":{"ydx":["Nhịp xoang chậm sinh lý","Block nhĩ thất độ III (hoàn toàn) có rối loạn huyết động, do thuốc và hoặc thiếu máu cơ tim","Block xoang nhĩ nhẹ","Rung nhĩ đáp ứng thất nhanh"]},"actions":["Ngưng thuốc chẹn beta, chẹn kênh canxi, xét nghiệm điện giải, men tim","Hội chẩn tim mạch can thiệp để tạo nhịp tạm thời qua tĩnh mạch và đánh giá mạch vành","Tạo nhịp qua da (tần số 70 lần/phút, tăng dòng đến khi bắt nhịp) cùng an thần giảm đau nhẹ khi còn tỉnh","Đặt nằm, gắn monitor và máy sốc điện kèm tạo nhịp qua da, thở oxy, lập đường truyền","Tiếp tục thuốc chẹn beta liều cao","Tiêm atropine 1 mg tĩnh mạch (có thể lặp lại mỗi 3 đến 5 phút, tối đa 3 mg)","Truyền dopamine 5 đến 20 µg/kg/phút hoặc adrenalin 2 đến 10 µg/phút nếu chưa có tạo nhịp","Điều trị ran phổi nhẹ bằng lợi tiểu thận trọng khi huyết áp ổn","Cho về nhà dùng thuốc uống và hẹn tái khám","Dùng thuốc chống loạn nhịp (amiodarone) để tăng nhịp"]}}'::jsonb,
  'f81351b6eb3767a63bf0ec2ffe5acbe698f7707eb47fd20249beb596ae10e7ed'
)
