values (
  'noi-cap-cuu-006',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-006","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-006-1","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị các rối loạn nhịp tim; Hướng dẫn quy trình cấp cứu nhịp chậm.","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị các rối loạn nhịp tim; Hướng dẫn quy trình cấp cứu nhịp chậm.","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị các rối loạn nhịp tim; Hướng dẫn quy trình cấp cứu nhịp chậm.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-brady-accaha-2018","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/30586772/","title":"American Heart Association. ACC AHA HRS Guideline on the Evaluation and Management of Patients with Bradycardia and Cardiac Conduction Delay, Circulation 2019;140:e382-e482. DOI: 10.1161/CIR.0000000000000628.","organization":null,"year_version":null,"citation":"American Heart Association. ACC AHA HRS Guideline on the Evaluation and Management of Patients with Bradycardia and Cardiac Conduction Delay, Circulation 2019;140:e382-e482. DOI: 10.1161/CIR.0000000000000628.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-cap-cuu-006-3","resource_type":"other","source":"Hội Tim mạch học Việt Nam. Khuyến cáo xử trí nhịp chậm.","title":"Hội Tim mạch học Việt Nam. Khuyến cáo xử trí nhịp chậm.","organization":null,"year_version":null,"citation":"Hội Tim mạch học Việt Nam. Khuyến cáo xử trí nhịp chậm.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Rung nhĩ đáp ứng thất nhanh","credit":"none"},{"text":"Block nhĩ thất độ III (hoàn toàn) có rối loạn huyết động, do thuốc và hoặc thiếu máu cơ tim","credit":"full"},{"text":"Block xoang nhĩ nhẹ","credit":"none"},{"text":"Nhịp xoang chậm sinh lý","credit":"none"}]},"action_options":[{"text":"Đặt nằm, gắn monitor và máy sốc điện kèm tạo nhịp qua da, thở oxy, lập đường truyền","time_minutes":2,"grade":"critical","rationale":"Mạch 32 lần/phút, huyết áp 80/46 là bất ổn huyết động."},{"text":"Tiêm atropine 1 mg tĩnh mạch (có thể lặp lại mỗi 3 đến 5 phút, tối đa 3 mg)","time_minutes":2,"grade":"critical","rationale":"Đáp ứng kém ở block thấp nhưng vẫn thử khi cấp cứu."},{"text":"Tạo nhịp qua da (tần số 70 lần/phút, tăng dòng đến khi bắt nhịp) cùng an thần giảm đau nhẹ khi còn tỉnh","time_minutes":5,"grade":"critical","rationale":"Biện pháp cầu nối khi atropine thất bại."},{"text":"Truyền dopamine 5 đến 20 µg/kg/phút hoặc adrenalin 2 đến 10 µg/phút nếu chưa có tạo nhịp","time_minutes":5,"grade":"critical","rationale":"Phác đồ thay thế khi thiếu máy tạo nhịp."},{"text":"Ngưng thuốc chẹn beta, chẹn kênh canxi, xét nghiệm điện giải, men tim","time_minutes":5,"grade":"critical","rationale":"Loại bỏ nguyên nhân thuốc."},{"text":"Hội chẩn tim mạch can thiệp để tạo nhịp tạm thời qua tĩnh mạch và đánh giá mạch vành","time_minutes":10,"grade":"recommended","rationale":"Chỉ định tạo nhịp tạm thời bằng điện cực tĩnh mạch."},{"text":"Điều trị ran phổi nhẹ bằng lợi tiểu thận trọng khi huyết áp ổn","time_minutes":15,"grade":"recommended","rationale":"Chỉ khi huyết áp cải thiện."},{"text":"Tiếp tục thuốc chẹn beta liều cao","time_minutes":3,"grade":"waste","rationale":"Làm nặng block nhĩ thất."},{"text":"Cho về nhà dùng thuốc uống và hẹn tái khám","time_minutes":0,"grade":"harmful","rationale":"Block hoàn toàn có triệu chứng có nguy cơ vô tâm thu."},{"text":"Dùng thuốc chống loạn nhịp (amiodarone) để tăng nhịp","time_minutes":0,"grade":"harmful","rationale":"Làm chậm thêm nhịp và hạ huyết áp."}],"teaching_explanation":"Block nhĩ thất hoàn toàn có triệu chứng là cấp cứu: atropine, tạo nhịp qua da hoặc vận mạch, rồi tạo nhịp tạm thời qua tĩnh mạch. Luôn rà soát thuốc và thiếu máu cơ tim."}'::jsonb,
  '9c3a76e5bd945ea24daa11467207d1241bcea49df9940f5e30e7e91f438f7ca0'
)
