insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-cap-cuu-007',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-cap-cuu-007","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau ngực dữ dội, vã mồ hôi, khó thở, huyết áp tụt, chi lạnh","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":63,"sex":"nam","patient_label":"Ông Đ. M. S."},"presentation":{"intro":"Phòng cấp cứu. Người đàn ông đau thắt ngực dữ dội hơn 3 giờ, nay vã mồ hôi, khó thở nằm không được, da lạnh, huyết áp tụt.","place":null,"clock":null,"night":false},"vitals":{"hr":118,"sbp":76,"dbp":50,"rr":32,"temperature_c":36.4,"spo2":86},"history":[{"question":"Đau ngực bắt đầu lúc nào, tính chất thế nào?","response":"Cách đây hơn 3 giờ, đau như đè nặng sau xương ức, lan tay trái, không giảm khi nghỉ."},{"question":"Khó thở thế nào, có nằm được không?","response":"Phải ngồi mới thở được, thở nhanh, ho bọt hồng nhẹ."},{"question":"Tiền sử bệnh tim, tăng huyết áp, đái tháo đường, hút thuốc?","response":"Tăng huyết áp, đái tháo đường, hút thuốc 30 năm, chưa từng khám tim."},{"question":"Thuốc đang dùng, dị ứng, dùng chống đông?","response":"Không dùng thuốc đều, chưa có dị ứng, không dùng chống đông."},{"question":"Choáng váng, ngất, tiểu ít?","response":"Choáng váng, tiểu ít từ sáng."},{"question":"Chấn thương ngực, sốt?","response":"Không."},{"question":"Ăn uống lần cuối?","response":"Ăn sáng sớm."}],"examination":[{"group":"K","item":"Tưới máu và tri giác","finding":"Vã mồ hôi, da lạnh nổi vân, thời gian đổ đầy mao mạch 5 giây, còn tỉnh."},{"group":"K","item":"Phổi","finding":"Ran ẩm dâng quá nửa hai phổi."},{"group":"K","item":"Tim","finding":"Tim nhanh, tiếng tim mờ, có tiếng thổi tâm thu mới ở mỏm."},{"group":"K","item":"Tĩnh mạch cổ","finding":"Tĩnh mạch cổ nổi, gan không to."},{"group":"K","item":"Bụng và chi","finding":"Bụng mềm, phù chi nhẹ."}],"investigations":[{"name":"Điện tim 12 chuyển đạo","duration_minutes":10,"result":"ST chênh lên rõ ở V1 đến V6, DI, aVL; nhịp xoang nhanh."},{"name":"Siêu âm tim tại giường","duration_minutes":15,"result":"Phân suất tống máu 25%, giảm động rộng thành trước; hở van hai lá mức độ vừa; không tràn dịch màng tim."},{"name":"Troponin hs, khí máu động mạch, lactate","duration_minutes":10,"result":"Troponin hs tăng cao; lactate 5,5 mmol/L; pH 7,29."},{"name":"X quang ngực thẳng tại giường","duration_minutes":10,"result":"Phù phổi huyết động hai phế trường, bóng tim to nhẹ."},{"name":"Điện giải đồ, creatinin, đường huyết, đông máu, công thức máu","duration_minutes":10,"result":"Creatinin 150 µmol/L, kali 4,1, đường huyết 11 mmol/L."},{"name":"CT ngực có cản quang tìm tách thành động mạch chủ trước khi xử trí","duration_minutes":40,"result":"Không phù hợp, làm chậm tái thông mạch vành khi điện tim ST chênh rõ."},{"name":"Chờ men tim lần hai rồi mới hội chẩn can thiệp","duration_minutes":10,"result":"Không chờ men tim khi ST chênh lên."}],"choices":{"diagnosis":{"ydx":["Tràn dịch màng ngoài tim chèn ép","Sốc nhiễm khuẩn","Thuyên tắc phổi lớn","Sốc tim do nhồi máu cơ tim cấp ST chênh lên thành trước"]},"actions":["Trì hoãn can thiệp để chờ men tim hoặc chờ huyết áp tự lên","Điện tim 12 chuyển đạo, kích hoạt hội chẩn tim mạch can thiệp cấp cứu, nhanh chóng chuyển phòng can thiệp","Chuẩn bị hỗ trợ tuần hoàn cơ học (bóng đối xung động mạch chủ, ECMO) khi kháng vận mạch","Dùng morphine liều cao tĩnh mạch nhanh dù thở ngắn","Aspirin 300 mg nhai hoặc 250 mg tĩnh mạch và thuốc kháng đông (heparin) theo phác đồ","Dùng chẹn beta hoặc thuốc giãn mạch nitrat liều cao","Đặt nội khí quản và thở máy nếu thất bại thông khí không xâm nhập hoặc rối loạn ý thức","Siêu âm tim, theo dõi huyết áp động mạch xâm nhập, nước tiểu","Đặt nằm đầu cao, thở oxy hoặc thông khí không xâm nhập, gắn monitor và lập đường truyền","Noradrenalin truyền tĩnh mạch để đạt huyết áp trung bình trên 65 mmHg, dobutamine khi cung lượng thấp","Truyền dịch lớn bù thể tích"]}}'::jsonb,
  '71abea5761d77026b42a0040cc1244909da16682b68de176d46312fb5dd60219'
)
