tial_indices":[0,1,2,3],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tràn dịch màng ngoài tim chèn ép","credit":"none"},{"text":"Sốc tim do nhồi máu cơ tim cấp ST chênh lên thành trước","credit":"full"},{"text":"Sốc nhiễm khuẩn","credit":"none"},{"text":"Thuyên tắc phổi lớn","credit":"none"}]},"action_options":[{"text":"Đặt nằm đầu cao, thở oxy hoặc thông khí không xâm nhập, gắn monitor và lập đường truyền","time_minutes":2,"grade":"critical","rationale":"Suy hô hấp do phù phổi, SpO2 86%."},{"text":"Điện tim 12 chuyển đạo, kích hoạt hội chẩn tim mạch can thiệp cấp cứu, nhanh chóng chuyển phòng can thiệp","time_minutes":5,"grade":"critical","rationale":"Tái thông mạch vành sớm là điều trị cơ bản của sốc tim do nhồi máu."},{"text":"Aspirin 300 mg nhai hoặc 250 mg tĩnh mạch và thuốc kháng đông (heparin) theo phác đồ","time_minutes":5,"grade":"critical","rationale":"Điều trị nền nhồi máu cơ tim cấp."},{"text":"Noradrenalin truyền tĩnh mạch để đạt huyết áp trung bình trên 65 mmHg, dobutamine khi cung lượng thấp","time_minutes":10,"grade":"critical","rationale":"Duy trì tưới máu cơ quan."},{"text":"Siêu âm tim, theo dõi huyết áp động mạch xâm nhập, nước tiểu","time_minutes":10,"grade":"critical","rationale":"Đánh giá cơ học van hai lá, chức năng thất."},{"text":"Đặt nội khí quản và thở máy nếu thất bại thông khí không xâm nhập hoặc rối loạn ý thức","time_minutes":10,"grade":"recommended","rationale":"Bảo đảm oxy hóa."},{"text":"Chuẩn bị hỗ trợ tuần hoàn cơ học (bóng đối xung động mạch chủ, ECMO) khi kháng vận mạch","time_minutes":15,"grade":"recommended","rationale":"Theo chỉ định của nhóm sốc tim."},{"text":"Truyền dịch lớn bù thể tích","time_minutes":3,"grade":"waste","rationale":"Nguy cơ phù phổi nặng hơn khi áp lực đổ đầy tăng."},{"text":"Dùng chẹn beta hoặc thuốc giãn mạch nitrat liều cao","time_minutes":0,"grade":"harmful","rationale":"Làm tụt huyết áp, làm nặng sốc."},{"text":"Trì hoãn can thiệp để chờ men tim hoặc chờ huyết áp tự lên","time_minutes":0,"grade":"harmful","rationale":"Mỗi phút chậm trễ tăng hoại tử cơ tim, tử vong."},{"text":"Dùng morphine liều cao tĩnh mạch nhanh dù thở ngắn","time_minutes":0,"grade":"harmful","rationale":"Ức chế hô hấp và hạ huyết áp thêm."}],"teaching_explanation":"Sốc tim do nhồi máu cơ tim cần vận mạch, hỗ trợ hô hấp và tái thông mạch vành sớm nhất; tránh truyền dịch ồ ạt và thuốc hạ áp."}'::jsonb,
